30	bool CanEmitPackedX2MathMACA(DataType t) {
31	  int lanes = t.lanes();
32	  if (lanes < 2 || lanes % 2 != 0) {
33	    return false;
34	  }
35	  if (t.is_bfloat16() || t.is_float16()) {
36	    return true;
37	  }
38	  return t.is_float() && t.bits() == 32;
39	}
40	
41	} // namespace
42	
43	struct MACAMath {
44	  std::string operator()(DataType t, std::string name) const {
45	    if (t.is_float()) {
46	      switch (t.bits()) {
47	      case 64:
48	        return name;
49	      case 32:
50	        return name + 'f';
51	      case 16:
52	        return 'h' + name;
53	      default:
54	        return "";
55	      }
56	    }
57	    return "";
58	  }
59	};
60	
61	struct MACAFastMath : public MACAMath {
62	  std::string operator()(DataType t, std::string name) const {
63	    if (t.is_float() && t.bits() == 32) {
64	      return "__" + name + 'f';
65	    } else {
66	      return MACAMath::operator()(t, name);
67	    }
68	    return "";
69	  }
70	};
71	
72	struct MACAFastMathTan : public MACAMath {
73	  std::string operator()(DataType t, std::string name) const {
74	    if (t.is_float()) {
75	      switch (t.bits()) {
76	      case 64:
77	        return name;
78	      case 32:
79	        return "__" + name + 'f';
80	      case 16:
81	        return 'h' + name;
82	      default:
83	        return "";
84	      }
85	    }
86	    return "";
87	  }
88	};
89	
90	struct MACAIEEEMath {
91	  std::string operator()(DataType t, std::string name,
92	                         std::string rounding_mode) const {
93	    if (t.is_float() && t.bits() == 32) {
94	      return "__" + name + '_' + rounding_mode;
95	    } else if (t.is_float() && t.bits() == 64) {
96	      return "__d" + name + "_" + rounding_mode;
97	    }
98	    return "";
99	  }
100	};
