102	static std::string GetTileLangFP8Type(DataType type) {
103	  std::stringstream stream;
104	  int32_t lanes = type.lanes();
105	  std::string vec;
106	  if (type.is_scalar()) {
107	    vec = "";
108	  } else if (lanes == 2) {
109	    vec = "_2";
110	  } else if (lanes == 4) {
111	    vec = "_4";
112	  } else if (lanes == 8) {
113	    vec = "_8";
114	  } else if (lanes == 16) {
115	    vec = "_16";
116	  } else if (lanes == 32) {
117	    vec = "_32";
118	  } else {
119	    LOG(FATAL)
120	        << "Only support scalar and vector types of width (2, 4, 8, 16, 32) "
121	           "for FP8";
122	  }
123	  if (type.is_float8_e4m3() || type.is_float8_e4m3fn()) {
124	    stream << "fp8_e4" << vec << "_t";
125	  } else if (type.is_float8_e5m2()) {
126	    stream << "fp8_e5" << vec << "_t";
127	  } else if (type.is_float8_e8m0fnu()) {
128	    stream << "fp8_e8" << vec << "_t";
129	  } else {
130	    LOG(FATAL) << "Unsupported FP8 type in MACA codegen but got " << type;
131	  }
132	  return stream.str();
133	}
134	
135	std::string GetTileLangFP6Type(DataType type) {
136	  std::stringstream stream;
137	  int32_t lanes = type.lanes();
138	  std::string vec;
139	  if (type.is_scalar()) {
140	    vec = "";
141	  } else if (lanes == 2) {
142	    vec = "x2";
143	  } else if (lanes == 4) {
144	    vec = "x4";
145	  } else if (lanes == 8) {
146	    vec = "x8";
147	  } else if (lanes == 16) {
148	    vec = "x16";
149	  } else {
150	    LOG(FATAL)
151	        << "Only support scalar and vector types of width (2, 4) for FP6";
152	  }
153	  stream << "__maca_fp6";
154	  std::string suffix;
155	  if (type.code() == DataType::kFloat6_e2m3fn) {
156	    suffix = "_e2m3";
157	  } else if (type.code() == DataType::kFloat6_e3m2fn) {
158	    suffix = "_e3m2";
159	  } else {
160	    LOG(FATAL) << "Unsupported FP6 type in MACA codegen";
161	  }
162	  stream << vec << suffix;
163	  return stream.str();
164	}
165	
166	std::string GetTileLangFP4Type(DataType type) {
167	  std::stringstream stream;
168	  int32_t lanes = type.lanes();
169	  std::string vec;
170	  if (type.is_scalar()) {
171	    vec = "";
172	  } else if (lanes == 2) {
173	    vec = "_2";
174	  } else if (lanes == 4) {
175	    vec = "_4";
176	  } else if (lanes == 8) {
177	    vec = "_8";
178	  } else if (lanes == 16) {
179	    vec = "_16";
180	  } else if (lanes == 32) {
181	    vec = "_32";
182	  } else if (lanes == 64) {
183	    vec = "_64";
184	  } else {
185	    LOG(FATAL) << "Only support scalar and vector types of width (2, 4, 8, 16, "
186	                  "32, 64) for FP4";
187	  }
188	
189	  std::string suffix;
190	  if (type.code() == DataType::kFloat4_e2m1fn) {
191	    suffix = "_e2";
192	  } else {
193	    LOG(FATAL) << "Unsupported FP4 type in MACA codegen";
194	  }
195	
196	  stream << "fp4" << suffix << vec << "_t";
197	  return stream.str();
