200	/*!
201	 * \brief Replace patterns with replacement strings.
202	 * \note should use std::format instead when codebase is ported to C++20.
203	 */
204	class Replacer {
205	public:
206	  void register_rule(const std::string &pattern,
207	                     const std::string &replacement) {
208	    _rules.emplace_back(pattern, replacement);
209	  }
210	  std::string rewrite(std::string str) {
211	    for (auto &&rule : _rules) {
212	      auto [pattern, replacement] = rule;
213	      size_t len = pattern.size();
214	      size_t new_len = replacement.size();
215	      size_t pos = str.find(pattern);
216	      while (pos != std::string::npos) {
217	        str = str.replace(pos, len, replacement);
218	        pos = str.find(pattern, pos + new_len);
219	      }
220	    }
221	    return str;
222	  }
223	  void empty_rules() { _rules.clear(); }
224	
225	private:
226	  std::vector<std::pair<std::string, std::string>> _rules;
227	};
