237	class LaunchConfigExtractor : public tirx::StmtVisitor {
238	private:
239	  void VisitStmt_(const AttrStmtNode *op) final {
240	    if (op->attr_key == tirx::attr::thread_extent) {
241	      IterVar iv = Downcast<IterVar>(op->node);
242	      if (iv->var->name_hint == "threadIdx.x" ||
243	          iv->thread_tag == "threadIdx.x") {
244	        threadIdx_x_ext = op->value;
245	      } else if (iv->var->name_hint == "threadIdx.y" ||
246	                 iv->thread_tag == "threadIdx.y") {
247	        threadIdx_y_ext = op->value;
248	      } else if (iv->var->name_hint == "threadIdx.z" ||
249	                 iv->thread_tag == "threadIdx.z") {
250	        threadIdx_z_ext = op->value;
251	      }
252	    } else if (op->attr_key == tl::attr::kMinBlocksPerSM) {
253	      if (const IntImmNode *v = op->value.as<IntImmNode>()) {
254	        min_blocks_per_sm = v->value;
255	      }
256	    }
257	    StmtVisitor::VisitStmt_(op);
258	  }
259	
260	public:
261	  PrimExpr threadIdx_x_ext = Integer(1);
262	  PrimExpr threadIdx_y_ext = Integer(1);
263	  PrimExpr threadIdx_z_ext = Integer(1);
264	  int64_t min_blocks_per_sm = 1; // default to 1
265	};
