267	class ClusterInfoExtractor : public tirx::StmtVisitor {
268	private:
269	  void VisitStmt(const PrimFunc &f) {
270	    if (f->GetAttr<Array<PrimExpr>>("cluster_dims").has_value()) {
271	      launch_with_cluster = true;
272	      auto cluster_dims = f->GetAttr<Array<PrimExpr>>("cluster_dims").value();
273	      cluster_grid_x_ext = cluster_dims[0].as<IntImmNode>()->value;
274	      cluster_grid_y_ext = cluster_dims[1].as<IntImmNode>()->value;
275	      cluster_grid_z_ext = cluster_dims[2].as<IntImmNode>()->value;
276	      ICHECK(cluster_grid_x_ext > 0 && cluster_grid_y_ext > 0 &&
277	             cluster_grid_z_ext > 0);
278	    }
279	    StmtVisitor::VisitStmt(f->body);
280	  }
281	
282	  bool launch_with_cluster = false;
283	  int64_t cluster_grid_x_ext = 1;
284	  int64_t cluster_grid_y_ext = 1;
285	  int64_t cluster_grid_z_ext = 1;
286	
287	public:
288	  std::optional<std::tuple<int64_t, int64_t, int64_t>>
289	  extract(const PrimFunc &f) {
290	    this->VisitStmt(f);
291	    if (launch_with_cluster) {
292	      return std::make_tuple(cluster_grid_x_ext, cluster_grid_y_ext,
293	                             cluster_grid_z_ext);
294	    }
295	    return std::nullopt;
296	  }
297	};
