299	void CodeGenTileLangMACA::PrintExtraAttrs(const PrimFunc &f) {
300	  LaunchConfigExtractor extractor;
301	  extractor(f->body);
302	  arith::Analyzer analyzer;
303	  PrimExpr threadIdx_ext =
304	      analyzer.Simplify(extractor.threadIdx_x_ext * extractor.threadIdx_y_ext *
305	                        extractor.threadIdx_z_ext);
306	  if (const IntImmNode *const threadIdx_ext_int =
307	          threadIdx_ext.as<IntImmNode>()) {
308	    if (threadIdx_ext_int->value == 1) {
309	      // unable to extract the number of threads per block, hence directly
310	      // return
311	      return;
312	    }
313	    stream << " __launch_bounds__(" << threadIdx_ext_int->value << ", "
314	           << extractor.min_blocks_per_sm << ")";
315	  }
316	}
