374	void CodeGenTileLangMACA::VisitStmt_(const tirx::ForNode *op) {
375	  if (op->kind == tirx::ForKind::kUnrolled) {
376	    PrintIndent();
377	    if (unroll_factor.count(op->loop_var.get())) {
378	      stream << "#pragma unroll "
379	             << PrintExpr(unroll_factor[op->loop_var.get()]) << "\n";
380	    } else {
381	      stream << "#pragma unroll\n";
382	    }
383	  }
384	  std::string extent =
385	      PrintExpr(arith::Analyzer().Simplify(op->extent + op->min));
386	  PrintIndent();
387	  std::string vid = AllocVarID(op->loop_var.get());
388	  std::string start = PrintExpr(op->min);
389	  stream << "for (";
390	  PrintType(op->loop_var.dtype(), stream);
391	  stream << ' ' << vid << " = " << start << "; " << vid << " < " << extent
392	         << "; ++" << vid << ") {\n";
393	  int for_scope = BeginScope();
394	  PrintStmt(op->body);
395	  this->EndScope(for_scope);
396	  PrintIndent();
397	  stream << "}\n";
398	}
