406	void CodeGenTileLangMACA::PrintType(DataType t, std::ostream &os) { // NOLINT(*)
407	  int lanes = t.lanes();
408	  if (t.is_handle()) {
409	    ICHECK(t.is_scalar()) << "do not yet support vector types";
410	    os << "void*";
411	    return;
412	  }
413	
414	  if (t.is_void()) {
415	    os << "void";
416	    return;
417	  }
418	
419	  if (t == tl::CuTensorMapType()) {
420	    os << "CUtensorMap";
421	    return;
422	  }
423	
424	  bool fail = false;
425	  if (t.is_float()) {
426	    switch (t.bits()) {
427	    case 16:
428	      if (t.is_scalar()) {
429	        os << "half_t";
430	      } else if (lanes <= 8) {
431	        // Emit MACA code to access fp16 vector elements.
432	        //
433	        // half4 is stored as uint2
434	        //
435	        // h4.x is emitted as *(half2*)(&(u2.x)).x
436	        // h4.y is emitted as *(half2*)(&(u2.x)).y
437	        // h4.z is emitted as *(half2*)(&(u2.y)).x
438	        // h4.w is emitted as *(half2*)(&(u2.y)).y
439	        //
440	        ICHECK_EQ(lanes % 2, 0) << "only support even lane for half type";
441	        os << "uint" << lanes / 2;
442	      } else {
443	        fail = true;
444	      }
445	      break;
446	    case 32:
447	      if (lanes <= 4) {
448	        os << "float";
449	      } else if (lanes <= 8) {
450	        // Emit MACA code to access fp32 vector elements for 4 < lanes <= 8.
451	        //
452	        // float8 is stored as ulonglong4
453	        //
454	        // f8.v1 is emitted as *(float2*)(&(ul4.x)).x
455	        // f8.v2 is emitted as *(float2*)(&(ul4.x)).y
456	        //
457	        ICHECK_EQ(lanes % 2, 0)
458	            << "only support even lane for float type with lanes > 4";
459	        os << "ulonglong" << lanes / 2;
460	      } else if (lanes == 16) {
461	        os << "float32x16";
462	        return;
463	      } else if (lanes == 32) {
464	        os << "float32x32";
465	        return;
466	      } else {
467	        fail = true;
468	      }
469	      break;
470	    case 64:
471	      os << "double";
472	      break;
473	    default:
474	      fail = true;
475	      break;
476	    }
477	    if (!fail && (t.is_scalar() || t.bits() == 16))
478	      return;
479	    if (!fail && (lanes > 4 && lanes <= 8 && t.bits() == 32))
480	      return;
481	    if (!fail && (lanes >= 2 && lanes <= 4)) {
482	      os << lanes;
483	      return;
484	    }
485	  } else if (t.is_bfloat16()) {
486	    enable_bf16_ = true;
487	    if (t.is_scalar()) {
488	      os << "bfloat16_t";
489	    } else if (lanes <= 8) {
490	      ICHECK_EQ(lanes % 2, 0) << "only support even lane for half type";
491	      os << "uint" << lanes / 2;
492	    } else if (lanes <= 16) {
493	      ICHECK_EQ(lanes % 4, 0) << "only support (mod 4 = 0) lanes for half type "
494	                                 "of more than 8 lanes";
495	      os << "ulonglong" << lanes / 4;
496	    } else {
497	      fail = true;
498	    }
499	    if (!fail)
500	      return;
501	  } else if (t.is_float8()) {
502	    enable_fp8_ = true;
503	    os << GetTileLangFP8Type(t);
504	    return;
505	  } else if (t.is_float6()) {
506	    enable_fp6_ = true;
507	    if (t.lanes() <= 4) {
508	      os << GetTileLangFP6Type(t);
509	    }
510	    return;
511	  } else if (t.is_tfloat32()) {
512	    if (t.is_scalar()) {
513	      os << "float";
514	    } else if (lanes <= 4) {
515	      os << "float" << lanes;
516	    } else if (lanes <= 8) {
517	      ICHECK_EQ(lanes % 2, 0)
518	          << "only support even lane for tfloat32 type with lanes > 4";
519	      os << "ulonglong" << lanes / 2;
520	    } else {
521	      fail = true;
522	    }
523	    if (!fail)
524	      return;
525	  } else if (t.is_float4()) {
526	    enable_fp4_ = true;
527	    if (t.lanes() <= 64) {
528	      os << GetTileLangFP4Type(t);
529	    } else {
530	      fail = true;
531	    }
532	    return;
533	  } else if (t == DataType::Bool()) {
534	    os << "bool";
535	    return;
536	  } else if (t.is_vector_bool()) {
537	    // MACA does not support bool vectors.
538	    // Use ushort vectors to represent instead.
539	    int n = t.lanes();
540	    if (n <= 4) {
541	      os << "ushort" << n;
542	      return;
543	    }
544	  } else if (t.is_uint() || t.is_int()) {
545	    if (t.is_uint()) {
546	      os << "u";
547	    }
548	    switch (t.bits()) {
549	    case 1: {
550	      if (t.is_scalar()) {
551	        os << "int";
552	        return;
553	      } else if (t.lanes() == 8) {
554	        os << "int8_t";
555	        return;
556	      } else if (t.lanes() == 16) {
557	        os << "int16_t";
558	        return;
559	      } else if (t.lanes() == 32) {
560	        os << "int";
561	        return;
562	      } else {
563	        LOG(FATAL) << "Cannot convert type " << t << " to MACA type!";
564	      }
565	    }
566	    case 4: {
567	      if (t.is_scalar()) {
568	        os << "int";
569	        return;
570	      } else if (t.lanes() == 4) {
571	        os << "int16_t";
572	        return;
573	      } else if (t.lanes() == 8) {
574	        // directly 8 4-bit int in integer.
575	        os << "int";
576	        return;
577	      } else if (t.lanes() == 16) {
578	        os << "int2";
579	        return;
580	      } else if (t.lanes() == 32) {
581	        os << "int4";
582	        return;
583	      } else if (t.lanes() == 64) {
584	        os << "int8";
585	        return;
586	      } else {
587	        LOG(FATAL) << "Cannot convert type " << t << " to MACA type!";
588	      }
589	    }
590	    case 8: {
591	      if (t.lanes() == 4) {
592	        // directly 4 8 bit int in integer.
593	        enable_int8_ = true;
594	
595	        // We use int for int8x4 instead of char4 because using char4 is
596	        // likely to produce extra instructions to pack four int8 elements
597	        // into 32-bit data.
598	        os << "int";
599	        return;
600	      } else if (t.lanes() == 8) {
601	        enable_int8_ = true;
602	        os << "int2";
603	        return;
604	      } else if (t.lanes() == 16) {
605	        enable_int8_ = true;
606	        os << "int4";
607	        return;
608	      } else if (t.lanes() == 32) {
609	        enable_int8_ = true;
610	        os << "longlong4";
611	        return;
612	      } else if (!t.is_uint() && t.is_scalar()) {
613	        os << "signed char";
614	        break;
615	      } else {
616	        os << "char";
617	        break;
618	      }
619	    }
620	    case 16: {
621	      if (t.is_scalar()) {
622	        os << "short";
623	      } else if (t.lanes() <= 4) {
624	        os << "short" << lanes;
625	      } else if (t.lanes() <= 8) {
626	        // Emit MACA code to access int16 vector elements.
627	        //
628	        // short4 is stored as int2
629	        //
630	        // s4.x is emitted as *(short2*)(&(i2.x)).x
631	        // s4.y is emitted as *(short2*)(&(i2.x)).y
632	        // s4.z is emitted as *(short2*)(&(i2.y)).x
633	        // s4.w is emitted as *(short2*)(&(i2.y)).y
634	        //
635	        ICHECK_EQ(t.lanes() % 2, 0)
636	            << "only support even lane for shorT type with lanes > 4";
637	        os << "int" << t.lanes() / 2;
638	      } else {
639	        fail = true;
640	      }
641	      if (!fail) {
642	        return;
643	      }
644	      break;
645	    }
646	    case 32: {
647	      if (t.is_scalar()) {
648	        os << "int";
649	      } else if (t.lanes() <= 4) {
650	        os << "int" << t.lanes();
651	      } else if (t.lanes() <= 8) {
652	        // Emit MACA code to access int32 vector elements for 4 < lanes <= 8.
653	        //
654	        // int8 is stored as longlong4
655	        //
656	        // i8.v1 is emitted as *(int2*)(&(l4.x)).x
657	        // i8.v2 is emitted as *(int2*)(&(l4.x)).y
658	        //
659	        ICHECK_EQ(lanes % 2, 0)
660	            << "only support even lane for int32 type with lanes > 4";
661	        os << "longlong" << lanes / 2;
662	      } else {
663	        fail = true;
664	      }
665	      if (!fail) {
666	        return;
667	      }
668	      break;
669	    }
670	    case 64: {
671	      if (t.is_scalar()) {
672	        os << "int64_t";
673	      } else if (t.lanes() == 2) {
674	        os << "longlong2";
675	      } else if (t.lanes() == 3) {
676	        os << "longlong3";
677	      } else if (t.lanes() == 4) {
678	        os << "longlong4";
679	      } else {
680	        fail = true;
681	      }
682	      if (!fail) {
683	        return;
684	      }
685	      break;
686	    }
687	    default:
688	      fail = true;
689	      break;
690	    }
691	    if (!fail && lanes == 1) {
692	      return;
693	    }
694	    if (!fail && (lanes >= 2 && lanes <= 4)) {
695	      os << lanes;
696	      return;
697	    }
698	  }
699	  LOG(FATAL) << "Cannot convert type " << t << " to MACA type";
700	}
