702	void CodeGenTileLangMACA::PrintVecBinaryOp(const std::string &op, DataType t,
703	                                           PrimExpr lhs, PrimExpr rhs,
704	                                           std::ostream &os) { // NOLINT(*)
705	  // Fast-path for packed x2 arithmetic (float32x2, maca_bfloat162, half2).
706	  int lanes = t.lanes();
707	  if (lanes >= 2 && lanes % 2 == 0) {
708	    bool is_bf16x2 = t.is_bfloat16();
709	    bool is_fp16x2 = t.is_float16();
710	    if (CanEmitPackedX2MathMACA(t)) {
711	      std::string tl_func;
712	      bool use_fma = false;
713	      PrimExpr fma_a, fma_b, fma_c;
714	
715	      if (op == "+") {
716	        // Fuse packed mul+add here instead of emitting separate tl::mul2 and
717	        // tl::add2 calls that may not contract back into tl::fma2.
718	        auto try_fuse_mul_add = [&](const PrimExpr &maybe_mul,
719	                                    const PrimExpr &addend) -> bool {
720	          const MulNode *mul = maybe_mul.as<MulNode>();
721	          if (mul == nullptr || mul->dtype != t || mul->a.dtype() != t ||
722	              mul->b.dtype() != t || addend.dtype() != t) {
723	            return false;
724	          }
725	          tl_func = "fma2";
726	          use_fma = true;
727	          fma_a = mul->a;
728	          fma_b = mul->b;
729	          fma_c = addend;
730	          return true;
731	        };
732	        if (!try_fuse_mul_add(lhs, rhs)) {
733	          try_fuse_mul_add(rhs, lhs);
734	        }
735	      }
736	
737	      if (tl_func.empty() && op == "+")
738	        tl_func = "add2";
739	      else if (op == "-")
740	        tl_func = "sub2";
741	      else if (op == "*")
742	        tl_func = "mul2";
743	      else if (op == "min")
744	        tl_func = "min2";
745	      else if (op == "max")
746	        tl_func = "max2";
747	      else if (op == "min_nan")
748	        tl_func = "min2_nan";
749	      else if (op == "max_nan")
750	        tl_func = "max2_nan";
751	
752	      if (!tl_func.empty()) {
753	        // Decompose into lanes/2 independent x2 packed operations.
754	        //
755	        // Vector type → MACA struct mapping:
756	        //   bf16/fp16 x2..x8  -> uint1..uint4  (one packed x2 pair per field)
757	        //   bf16/fp16 x12/x16 -> ulonglong3/4 (two packed x2 pairs per field)
758	        //   f32x2  -> float2 {.x, .y}
759	        //   f32x4  -> float4 {.x,.y,.z,.w}
760	        //   f32x6/x8 -> ulonglong3/4 (one float2 pair per field)
761	        int num_pairs = lanes / 2;
762	        static const char access[] = {'x', 'y', 'z', 'w'};
763	
764	        std::string sret = name_supply_->FreshName("_");
765	        this->PrintIndent();
766	        this->PrintType(t, stream);
767	        stream << ' ' << sret << ";\n";
768	        int ssa_scope = BeginScope();
769	        {
770	          std::vector<std::string> packed_vecs;
771	          if (use_fma) {
772	            packed_vecs = {
773	                SSAGetID(PrintExpr(fma_a), fma_a.dtype()),
774	                SSAGetID(PrintExpr(fma_b), fma_b.dtype()),
775	                SSAGetID(PrintExpr(fma_c), fma_c.dtype()),
776	            };
777	          } else {
778	            packed_vecs = {
779	                SSAGetID(PrintExpr(lhs), lhs.dtype()),
780	                SSAGetID(PrintExpr(rhs), rhs.dtype()),
781	            };
782	          }
783	
784	          if (is_bf16x2 || is_fp16x2) {
785	            std::string native_type = is_bf16x2 ? "maca_bfloat162" : "half2";
786	            auto make_half_pair = [&](const std::string &vec_name,
787	                                      const std::string &field,
788	                                      int pair_offset) {
789	              std::string pair = "tl::from_uint1<";
790	              pair += native_type;
791	              pair += ">(";
792	              if (lanes <= 8) {
793	                pair += "*(uint1*)(&(";
794	                pair += vec_name;
795	                pair += ".";
796	                pair += field;
797	                pair += "))";
798	              } else {
799	                pair += "*(((uint1*)(&(";
800	                pair += vec_name;
801	                pair += ".";
802	                pair += field;
803	                pair += "))) + ";
804	                pair += std::to_string(pair_offset);
805	                pair += ")";
806	              }
807	              pair += ")";
808	              return pair;
809	            };
810	            for (int p = 0; p < num_pairs; ++p) {
811	              int field_idx = lanes <= 8 ? p : (p / 2);
812	              ICHECK_LT(field_idx, 4);
813	              int pair_offset = lanes <= 8 ? 0 : (p % 2);
814	              std::string field(1, access[field_idx]);
815	              std::vector<std::string> pair_args;
816	              pair_args.reserve(packed_vecs.size());
817	              for (const auto &vec_name : packed_vecs) {
818	                pair_args.push_back(
819	                    make_half_pair(vec_name, field, pair_offset));
820	              }
821	              this->PrintIndent();
822	              if (lanes <= 8) {
823	                stream << "*(uint1*)(&(" << sret << "." << field
824	                       << ")) = tl::to_uint1(tl::" << tl_func << "(";
825	              } else {
826	                stream << "*(((uint1*)(&(" << sret << "." << field << "))) + "
827	                       << pair_offset << ") = tl::to_uint1(tl::" << tl_func
828	                       << "(";
829	              }
830	              stream << pair_args[0];
831	              for (size_t i = 1; i < pair_args.size(); ++i) {
832	                stream << ", " << pair_args[i];
833	              }
834	              stream << "));\n";
835	            }
836	          } else {
837	            // f32: reinterpret lane pairs as float2. For float4, pairs are at
838	            // .x and .z; for ulonglong3/4, one float2 per field.
839	            auto make_float_pair = [&](const std::string &vec_name,
840	                                       const std::string &field) {
841	              return "*(float2*)(&(" + vec_name + "." + field + "))";
842	            };
843	            for (int p = 0; p < num_pairs; ++p) {
844	              int field_idx = lanes <= 4 ? (p * 2) : p;
845	              ICHECK_LT(field_idx, 4);
846	              std::string field(1, access[field_idx]);
847	              std::vector<std::string> pair_args;
848	              pair_args.reserve(packed_vecs.size());
849	              for (const auto &vec_name : packed_vecs) {
850	                pair_args.push_back(make_float_pair(vec_name, field));
851	              }
852	              this->PrintIndent();
853	              stream << "*(float2*)(&(" << sret << "." << field
854	                     << ")) = tl::" << tl_func << "(" << pair_args[0];
855	              for (size_t i = 1; i < pair_args.size(); ++i) {
856	                stream << ", " << pair_args[i];
857	              }
858	              stream << ");\n";
859	            }
860	          }
861	        }
862	        EndScope(ssa_scope);
863	        os << sret;
864	        return;
865	      }
866	    }
867	  }
868	
869	  // Declare the result.
870	  std::string sret = name_supply_->FreshName("_");
871	  this->PrintIndent();
872	  this->PrintType(t, stream);
873	  stream << ' ' << sret << ";\n";
874	  int ssa_scope = BeginScope();
875	  {
876	    // Unpack into individual ops.
877	    std::string vlhs = SSAGetID(PrintExpr(lhs), lhs.dtype());
878	    std::string vrhs = SSAGetID(PrintExpr(rhs), rhs.dtype());
879	
880	    for (int i = 0, lanes = t.lanes(); i < lanes; ++i) {
881	      std::ostringstream value_temp;
882	      if (isalpha(op[0])) {
883	        value_temp << op << "(";
884	        PrintVecElemLoad(vlhs, lhs.dtype(), i, value_temp);
885	        value_temp << ", ";
886	        PrintVecElemLoad(vrhs, rhs.dtype(), i, value_temp);
887	        value_temp << ")";
888	      } else {
889	        value_temp << "(";
890	        PrintVecElemLoad(vlhs, lhs.dtype(), i, value_temp);
891	        value_temp << op;
892	        PrintVecElemLoad(vrhs, rhs.dtype(), i, value_temp);
893	        value_temp << ")";
894	      }
895	      PrintVecElemStore(sret, t, i, value_temp.str());
896	    }
897	  }
898	  EndScope(ssa_scope);
899	  os << sret;
900	}
