902	void CodeGenTileLangMACA::PrintVecElemLoad(const std::string &vec, DataType t,
903	                                           int i,
904	                                           std::ostream &os) { // NOLINT(*)
905	  if (t.is_scalar()) {
906	    os << vec;
907	    return;
908	  }
909	
910	  static const char access[] = {'x', 'y', 'z', 'w'};
911	  ICHECK(i >= 0 && i < (t.bits() == 8                        ? 16
912	                        : (t.lanes() == 16)                  ? 16
913	                        : (t.lanes() == 32)                  ? 32
914	                        : (t.bits() == 16 || t.bits() == 32) ? 8
915	                                                             : 4));
916	  if (t.bits() == 8 && (t.is_int() || t.is_uint())) {
917	    std::string type_name = t.is_int() ? "char" : "unsigned char";
918	    if (t.lanes() == 2 || t.lanes() == 3) {
919	      os << vec << "." << access[i % t.lanes()];
920	    } else if (t.lanes() <= 16) {
921	      std::string ac = t.lanes() == 4 ? vec : (vec + "." + access[i / 4]);
922	      os << "((" << type_name << ")(" << ac << " >> " << i % 4 * 8 << "))";
923	    } else {
924	      ICHECK(t.lanes() == 32);
925	      std::string ac = vec + "." + access[i / 8];
926	      os << "((" << type_name << ")(" << ac << " >> " << i % 8 * 8 << "))";
927	    }
928	  } else if ((t.lanes() == 16 || t.lanes() == 32) && t.bits() == 32 &&
929	             t.is_float()) {
930	    os << vec << "[" << i << "]";
931	  } else if (t.is_float16()) {
932	    if (t.lanes() <= 8) {
933	      os << "((half2*)(&(" << vec << "." << access[i / 2] << ")))->"
934	         << access[i % 2];
935	    } else {
936	      os << "(((half2*)(&(" << vec << "." << access[i / 4] << "))) + "
937	         << (i / 2 % 2) << ")->" << access[i % 2];
938	    }
939	  } else if (t.is_bfloat16()) {
940	    if (t.lanes() <= 8) {
941	      os << "((maca_bfloat162*)(&(" << vec << "." << access[i / 2] << ")))->"
942	         << access[i % 2];
943	    } else {
944	      os << "(((maca_bfloat162*)(&(" << vec << "." << access[i / 4] << "))) + "
945	         << (i / 2 % 2) << ")->" << access[i % 2];
946	    }
947	  } else if (t.is_float8()) {
948	    os << vec;
949	    // fp8_e5_32_t
950	    if (t.lanes() >= 32)
951	      os << "." << access[i / 16];
952	    // fp8_e5_16_t
953	    if (t.lanes() >= 16)
954	      os << "." << access[(i % 16) / 8];
955	    // fp8_e5_8_t
956	    if (t.lanes() >= 8)
957	      os << "." << access[(i % 8) / 4];
958	    // fp8_e5_4_t or fp8_e5_2_t
959	    os << "." << access[i % 4];
960	  } else if (t.is_float4_e2m1fn()) {
961	    os << vec;
962	    // fp4_e2_64_t
963	    if (t.lanes() >= 64)
964	      os << "." << access[i / 32];
965	    // fp4_e2_32_t
966	    if (t.lanes() >= 32)
967	      os << "." << access[(i % 32) / 16];
968	    // fp4_e2_16_t
969	    if (t.lanes() >= 16)
970	      os << "." << access[(i % 16) / 8];
971	    // fp4_e2_8_t
972	    if (t.lanes() >= 8)
973	      os << "." << access[(i % 8) / 4];
974	    // fp4_e2_4_t -> fp4_e2_2_t member
975	    if (t.lanes() >= 4)
976	      os << "." << access[(i % 4) / 2];
977	    // fp4_e2_2_t -> method call x() or y()
978	    os << "." << access[i % 2] << "()";
979	  } else if (t.lanes() > 4 && t.lanes() <= 8) {
980	    std::string type_name;
981	    if (t.bits() == 16) {
982	      if (t.is_int()) {
983	        type_name = "short";
984	      } else if (t.is_uint()) {
985	        type_name = "ushort";
986	      }
987	    } else if (t.bits() == 32) {
988	      if (t.is_int()) {
989	        type_name = "int";
990	      } else if (t.is_uint()) {
991	        type_name = "uint";
992	      } else if (t.is_float()) {
993	        type_name = "float";
994	      }
995	    }
996	    ICHECK(!type_name.empty());
997	    os << "((" << type_name << "2*)(&(" << vec << "." << access[i / 2]
998	       << ")))->" << access[i % 2];
999	  } else {
1000	    os << vec << "." << access[i];
1001	  }
1002	}
