1004	void CodeGenTileLangMACA::PrintVecElemStore(const std::string &vec, DataType t,
1005	                                            int i, const std::string &value) {
1006	  this->PrintIndent();
1007	  static const char access[] = {'x', 'y', 'z', 'w'};
1008	  ICHECK(i >= 0 && i < (t.bits() == 8                        ? 16
1009	                        : (t.lanes() == 16)                  ? 16
1010	                        : (t.lanes() == 32)                  ? 32
1011	                        : (t.bits() == 16 || t.bits() == 32) ? 8
1012	                                                             : 4));
1013	  if (t.bits() == 8 && (t.is_int() || t.is_uint())) {
1014	    if (t.lanes() == 2 || t.lanes() == 3) {
1015	      stream << vec << '.' << access[i % t.lanes()] << "="
1016	             << "(" << value << ");\n";
1017	    } else if (t.lanes() <= 16) {
1018	      std::string ac = t.lanes() == 4 ? vec : (vec + "." + access[i / 4]);
1019	      stream << ac << "=";
1020	      // Do not read the first undef lane.
1021	      if (i != 0) {
1022	        stream << ac << " & ~(0x000000ff << " << i % 4 * 8 << ") |";
1023	      }
1024	      stream << "(" << value << " << " << i % 4 * 8 << ");\n";
1025	    } else {
1026	      ICHECK(t.lanes() == 32);
1027	      std::string ac = vec + "." + access[i / 8];
1028	      stream << ac << "=";
1029	      // Do not read the first undef lane.
1030	      if (i != 0) {
1031	        stream << ac << " & ~(0x000000ff << " << i % 8 * 8 << ") |";
1032	      }
1033	      stream << "(" << value << " << " << i % 8 * 8 << ");\n";
1034	    }
1035	  } else if ((t.lanes() == 16 || t.lanes() == 32) && t.bits() == 32 &&
1036	             t.is_float()) {
1037	    stream << vec << "[" << i << "] = " << value << ";\n";
1038	  } else if (t.is_float16()) {
1039	    if (t.lanes() <= 8) {
1040	      stream << "((half2*)(&(" << vec << "." << access[i / 2] << ")))->"
1041	             << access[i % 2] << " = " << value << ";\n";
1042	    } else {
1043	      stream << "(((half2*)(&(" << vec << "." << access[i / 4] << "))) + "
1044	             << (i / 2 % 2) << ")->" << access[i % 2] << " = " << value
1045	             << ";\n";
1046	    }
1047	  } else if (t.is_bfloat16()) {
1048	    if (t.lanes() <= 8) {
1049	      stream << "((maca_bfloat162*)(&(" << vec << "." << access[i / 2]
1050	             << ")))->" << access[i % 2] << " = " << value << ";\n";
1051	    } else {
1052	      stream << "(((maca_bfloat162*)(&(" << vec << "." << access[i / 4]
1053	             << "))) + " << (i / 2 % 2) << ")->" << access[i % 2] << " = "
1054	             << value << ";\n";
1055	    }
1056	  } else if (t.is_float8()) {
1057	    stream << vec;
1058	    // fp8_e5_32_t
1059	    if (t.lanes() >= 32)
1060	      stream << "." << access[i / 16];
1061	    // fp8_e5_16_t
1062	    if (t.lanes() >= 16)
1063	      stream << "." << access[(i % 16) / 8];
1064	    // fp8_e5_8_t
1065	    if (t.lanes() >= 8)
1066	      stream << "." << access[(i % 8) / 4];
1067	    // fp8_e5_4_t or fp8_e5_2_t
1068	    stream << "." << access[i % 4] << " = " << value << ";\n";
1069	  } else if (t.lanes() > 4 && t.lanes() <= 8) {
1070	    std::string type_name;
1071	    if (t.bits() == 16) {
1072	      if (t.is_int()) {
1073	        type_name = "short";
1074	      } else if (t.is_uint()) {
1075	        type_name = "ushort";
1076	      }
1077	    } else if (t.bits() == 32) {
1078	      if (t.is_int()) {
1079	        type_name = "int";
1080	      } else if (t.is_uint()) {
1081	        type_name = "uint";
1082	      } else if (t.is_float()) {
1083	        type_name = "float";
1084	      }
1085	    }
1086	    ICHECK(!type_name.empty());
1087	    stream << "((" << type_name << "2*)(&(" << vec << "." << access[i / 2]
1088	           << ")))->" << access[i % 2] << " = " << value << ";\n";
1089	  } else if (t.is_float4_e2m1fn()) {
1090	    stream << vec;
1091	    // fp4_e2_64_t
1092	    if (t.lanes() >= 64)
1093	      stream << "." << access[i / 32];
1094	    // fp4_e2_32_t
1095	    if (t.lanes() >= 32)
1096	      stream << "." << access[(i % 32) / 16];
1097	    // fp4_e2_16_t
1098	    if (t.lanes() >= 16)
1099	      stream << "." << access[(i % 16) / 8];
1100	    // fp4_e2_8_t
1101	    if (t.lanes() >= 8)
1102	      stream << "." << access[(i % 8) / 4];
1103	    // fp4_e2_4_t -> fp4_e2_2_t member
1104	    if (t.lanes() >= 4)
1105	      stream << "." << access[(i % 4) / 2];
1106	    // fp4_e2_2_t -> set_x() or set_y()
1107	    stream << ".set_" << access[i % 2] << "(" << value << ");\n";
1108	  } else {
1109	    stream << vec << "." << access[i] << " = " << value << ";\n";
1110	  }
1111	}
