1113	void CodeGenTileLangMACA::PrintStorageSync(const CallNode *op) {
1114	  auto args = op->args;
1115	  const std::string &sync = op->args[0].as<StringImmNode>()->value;
1116	  if (sync == "warp") {
1117	    // DO nothing.
1118	  } else if (sync == "shared" || sync == "shared.dyn") {
1119	    this->PrintIndent();
1120	    if (args.size() == 1) {
1121	      this->stream << "__syncthreads();\n";
1122	    } else if (args.size() == 2) {
1123	      auto barrier_id = args[1].as<IntImmNode>()->value;
1124	      this->stream << "tl::__sync_thread_partial<" << barrier_id << ">();\n";
1125	    } else if (args.size() == 3) {
1126	      auto barrier_id = args[1].as<IntImmNode>()->value;
1127	      auto thread_count = args[2].as<IntImmNode>()->value;
1128	      this->stream << "tl::__sync_thread_partial<" << barrier_id << ", "
1129	                   << thread_count << ">();\n";
1130	    } else {
1131	      LOG(FATAL) << "Invalid number of arguments for storage sync: "
1132	                 << args.size();
1133	    }
1134	  } else if (sync == "global") {
1135	    LOG(FATAL) << "Global storage sync is no longer supported";
1136	  }
1137	}
