1151	std::string CodeGenTileLangMACA::CastFromTo(std::string value, DataType from,
1152	                                            DataType target) {
1153	  if (from == target)
1154	    return value;
1155	  std::ostringstream os;
1156	  os << "((";
1157	  this->PrintType(target, os);
1158	  os << ")";
1159	  if (from.is_float16() && (target.is_int() || target.is_uint()) &&
1160	      target.bits() == 8) {
