1170	
1171	void CodeGenTileLangMACA::VisitExpr_(const CastNode *op, std::ostream &os) {
1172	  DataType from_ty = op->value.dtype();
1173	  DataType target_ty = op->dtype;
1174	  ICHECK_EQ(target_ty.lanes(), from_ty.lanes());
1175	
1176	  // Decode the optional rounding/saturation/rbits hints stashed in
1177	  // `op->annotations` (see CastNode docstring for the convention).
1178	  auto get_str_anno = [&](const char *key) -> std::string {
1179	    auto it = op->annotations.find(key);
1180	    if (it == op->annotations.end())
1181	      return "";
1182	    return Downcast<StringImm>((*it).second)->value;
1183	  };
1184	  auto get_bool_anno = [&](const char *key, bool dflt) -> bool {
1185	    auto it = op->annotations.find(key);
1186	    if (it == op->annotations.end())
1187	      return dflt;
1188	    return Downcast<IntImm>((*it).second)->value != 0;
1189	  };
1190	  auto get_expr_anno = [&](const char *key) -> Optional<PrimExpr> {
1191	    auto it = op->annotations.find(key);
1192	    if (it == op->annotations.end())
1193	      return std::nullopt;
1194	    return Downcast<PrimExpr>((*it).second);
1195	  };
1196	  std::string cast_round = get_str_anno("round");
1197	  bool cast_sat = get_bool_anno("sat", true);
1198	  Optional<PrimExpr> cast_rbits = get_expr_anno("rbits");
1199	
1200	  // Scalar fp8 <-> half via the __tl_cvt helpers; the default cast detours
1201	  // through fp32.
1202	  if (from_ty.is_scalar() && cast_round.empty() && target_ty.is_float16() &&
1203	      tl::IsMacaVectorizableFP8(from_ty)) {
1204	    bool is_e4m3 = from_ty.is_float8_e4m3() || from_ty.is_float8_e4m3fn();
1205	    std::string interp = is_e4m3 ? "__MACA_E4M3" : "__MACA_E5M2";
1206	    os << "half_t(__tl_cvt_fp8_to_half((" << PrintExpr(op->value) << "), "
1207	       << interp << "))";
1208	    return;
1209	  }
1210	
1211	  if (from_ty.is_scalar() && cast_round.empty() && from_ty.is_float16() &&
1212	      tl::IsMacaVectorizableFP8(target_ty)) {
1213	    bool is_e4m3 = target_ty.is_float8_e4m3() || target_ty.is_float8_e4m3fn();
1214	    std::string interp = is_e4m3 ? "__MACA_E4M3" : "__MACA_E5M2";
1215	    this->PrintType(target_ty, os);
1216	    os << "::bitcast(__tl_cvt_half_to_fp8((" << PrintExpr(op->value)
1217	       << ").to_half(), " << interp << "))";
1218	    return;
1219	  }
1220	
1221	  // Scalar fp8 <-> bfloat16: same idea, via the native/PTX helpers.
1222	  if (from_ty.is_scalar() && cast_round.empty() && target_ty.is_bfloat16() &&
1223	      tl::IsMacaVectorizableFP8(from_ty)) {
1224	    bool is_e4m3 = from_ty.is_float8_e4m3() || from_ty.is_float8_e4m3fn();
1225	    std::string interp = is_e4m3 ? "__MACA_E4M3" : "__MACA_E5M2";
1226	    os << "bfloat16_t(__tl_cvt_fp8_to_bfloat16((" << PrintExpr(op->value)
1227	       << "), " << interp << "))";
1228	    return;
1229	  }
1230	
1231	  if (from_ty.is_scalar() && cast_round.empty() && from_ty.is_bfloat16() &&
1232	      tl::IsMacaVectorizableFP8(target_ty)) {
1233	    bool is_e4m3 = target_ty.is_float8_e4m3() || target_ty.is_float8_e4m3fn();
1234	    std::string interp = is_e4m3 ? "__MACA_E4M3" : "__MACA_E5M2";
1235	    this->PrintType(target_ty, os);
1236	    os << "::bitcast(__tl_cvt_bfloat16_to_fp8((" << PrintExpr(op->value)
1237	       << ").to_maca_bfloat16(), " << interp << "))";
1238	    return;
1239	  }
1240	
1241	  // Emit simple C-style type conversion.
1242	  if (from_ty.is_scalar())
1243	    return CodeGenC::VisitExpr_(op, os);
1244	
1245	  // We could emit make_float4 like calls, but the emitted code looks
1246	  // too compact to read. Emit this as vectorized unary ops.
1247	  std::string sret = name_supply_->FreshName("_");
1248	  this->PrintIndent();
1249	  this->PrintType(target_ty, stream);
1250	  stream << ' ' << sret << ";\n";
1251	  std::string src = SSAGetID(PrintExpr(op->value), from_ty);
1252	
1253	  int lanes = from_ty.lanes();
1254	
1255	  auto PrintVectorizedCast =
1256	      [&](const std::string &cast_func, const std::string &src_type,
1257	          const std::string &dst_type, const std::string &extra_args = "",
1258	          bool src_needs_reinterpret = false,
1259	          bool dst_needs_reinterpret = false) {
1260	        int num_chunks = lanes / 2;
1261	        std::string src_cast = src_needs_reinterpret
1262	                                   ? "reinterpret_cast<" + src_type + "*>"
1263	                                   : "(" + src_type + "*)";
1264	        std::string dst_cast = dst_needs_reinterpret
1265	                                   ? "reinterpret_cast<" + dst_type + "*>"
1266	                                   : "(" + dst_type + "*)";
1267	
1268	        for (int i = 0; i < num_chunks; i++) {
1269	          PrintIndent();
1270	          stream << "(" << dst_cast << "(&" << sret << "))[" << i
1271	                 << "] = " << cast_func << "((" << src_cast << "(&" << src
1272	                 << "))[" << i << "]" << extra_args << ");\n";
1273	        }
1274	        os << sret;
1275	      };
1276	
1277	  // A list of casting functions that are supported by TileLang templates.
1278	  // To add a new type conversion, you should do the following things:
1279	  // 1. Add the new conversion function in tl_templates. (__tl_cvt_xx)
1280	  // 2. Add a new if statement like the one below.
1281	  // 3. In src/target/utils.cc, allow this vectorizable cast.
1282	
1283	  // Handle conversion from float16 to float32
1284	  if (from_ty.is_float16() && target_ty.is_float() && target_ty.bits() == 32) {
1285	    // Use __half22float2 for vectorized conversion (half2 -> float2)
1286	    if (lanes == 2 || lanes == 4 || lanes == 8) {
1287	      PrintVectorizedCast("__half22float2", "half2", "float2");
1288	      return;
1289	    }
1290	  }
1291	
1292	  // Handle conversion from float32 to float16
1293	  if (from_ty.is_float() && from_ty.bits() == 32 && target_ty.is_float16()) {
1294	    // Use __float22half2_rn for vectorized conversion (float2 -> half2)
1295	    if (lanes == 2 || lanes == 4 || lanes == 8) {
1296	      PrintVectorizedCast("__float22half2_rn", "float2", "half2");
1297	      return;
1298	    }
1299	  }
1300	
1301	  // Handle conversion from bfloat16 to float32
1302	  if (from_ty.is_bfloat16() && target_ty.is_float() && target_ty.bits() == 32) {
1303	    // Use __bfloat1622float2 for vectorized conversion (bfloat162 -> float2)
1304	    if (lanes == 2 || lanes == 4 || lanes == 8) {
1305	      PrintVectorizedCast("__bfloat1622float2", "__maca_bfloat162", "float2",
1306	                          "", true, false);
1307	      return;
1308	    }
1309	  }
1310	
1311	  // Handle conversion from float32 to bfloat16
1312	  if (from_ty.is_float() && from_ty.bits() == 32 && target_ty.is_bfloat16()) {
1313	    // Use __float22bfloat162_rn for vectorized conversion (float2 -> bfloat162)
1314	    if (lanes == 2 || lanes == 4 || lanes == 8) {
1315	      PrintVectorizedCast("__float22bfloat162_rn", "float2", "__maca_bfloat162",
1316	                          "", false, true);
1317	      return;
1318	    }
1319	  }
1320	
1321	  // Handle conversion from float32 to float8 (E4M3/E5M2)
1322	  if (from_ty.is_float() && from_ty.bits() == 32 &&
1323	      tl::IsMacaVectorizableFP8(target_ty)) {
1324	    bool target_type_is_e4m3 =
1325	        target_ty.is_float8_e4m3() || target_ty.is_float8_e4m3fn();
1326	    std::string type_suffix =
1327	        target_type_is_e4m3 ? "__MACA_E4M3" : "__MACA_E5M2";
1328	
1329	    // Use __maca_cvt_float2_to_fp8x2 for vectorized conversion (float2 ->
1330	    // fp8x2)
1331	    if (lanes == 2 || lanes == 4 || lanes == 8) {
1332	      std::string extra_args = ", __MACA_SATFINITE, " + type_suffix;
1333	      PrintVectorizedCast("__maca_cvt_float2_to_fp8x2", "float2",
1334	                          "__maca_fp8x2_storage_t", extra_args, false, true);
1335	      return;
1336	    }
1337	  }
1338	
1339	  // Handle conversion from float16 to float8 (E4M3/E5M2)
1340	  if (from_ty.is_float16() && tl::IsMacaVectorizableFP8(target_ty)) {
1341	    bool target_type_is_e4m3 =
1342	        target_ty.is_float8_e4m3() || target_ty.is_float8_e4m3fn();
1343	    std::string type_suffix =
1344	        target_type_is_e4m3 ? "__MACA_E4M3" : "__MACA_E5M2";
1345	    // Use __tl_cvt_half2_to_fp8x2 for vectorized conversion (half2 -> fp8x2)
1346	    if (lanes == 2 || lanes == 4 || lanes == 8) {
1347	      PrintVectorizedCast("__tl_cvt_half2_to_fp8x2", "half2",
1348	                          "__maca_fp8x2_storage_t", ", " + type_suffix, false,
1349	                          true);
1350	      return;
1351	    }
1352	  }
1353	
1354	  // Handle conversion from bfloat16 to float8 (E4M3/E5M2)
1355	  if (from_ty.is_bfloat16() && tl::IsMacaVectorizableFP8(target_ty)) {
1356	    bool target_type_is_e4m3 =
1357	        target_ty.is_float8_e4m3() || target_ty.is_float8_e4m3fn();
1358	    std::string type_suffix =
1359	        target_type_is_e4m3 ? "__MACA_E4M3" : "__MACA_E5M2";
1360	    // Use __tl_cvt_bfloat162_to_fp8x2 for vectorized conversion (bfloat162 ->
1361	    // fp8x2)
1362	    if (lanes == 2 || lanes == 4 || lanes == 8) {
1363	      PrintVectorizedCast("__tl_cvt_bfloat162_to_fp8x2", "__maca_bfloat162",
1364	                          "__maca_fp8x2_storage_t", ", " + type_suffix, true,
1365	                          true);
1366	      return;
1367	    }
1368	  }
1369	
1370	  // Handle conversion from float8 (E4M3/E5M2) to float32
1371	  if (tl::IsMacaVectorizableFP8(from_ty) && target_ty.is_float() &&
1372	      target_ty.bits() == 32) {
1373	    bool from_type_is_e4m3 =
1374	        from_ty.is_float8_e4m3() || from_ty.is_float8_e4m3fn();
1375	    std::string type_suffix = from_type_is_e4m3 ? "__MACA_E4M3" : "__MACA_E5M2";
1376	
1377	    // Use __tl_cvt_fp8x2_to_float2 for vectorized conversion (fp8x2 -> float2)
1378	    if (lanes == 2 || lanes == 4 || lanes == 8) {
1379	      PrintVectorizedCast("__tl_cvt_fp8x2_to_float2", "__maca_fp8x2_storage_t",
1380	                          "float2", ", " + type_suffix, true, false);
1381	      return;
1382	    }
1383	  }
1384	
1385	  // Handle conversion from float8 (E4M3/E5M2) to float16
1386	  if (tl::IsMacaVectorizableFP8(from_ty) && target_ty.is_float16()) {
1387	    bool from_type_is_e4m3 =
1388	        from_ty.is_float8_e4m3() || from_ty.is_float8_e4m3fn();
1389	    std::string type_suffix = from_type_is_e4m3 ? "__MACA_E4M3" : "__MACA_E5M2";
1390	    // Use __tl_cvt_fp8x2_to_half2 for vectorized conversion (fp8x2 -> half2)
1391	    if (lanes == 2 || lanes == 4 || lanes == 8) {
1392	      PrintVectorizedCast("__tl_cvt_fp8x2_to_half2", "__maca_fp8x2_storage_t",
1393	                          "half2", ", " + type_suffix, true, false);
1394	      return;
1395	    }
1396	  }
1397	
1398	  // Handle conversion from float8 (E4M3/E5M2) to bfloat16
1399	  if (tl::IsMacaVectorizableFP8(from_ty) && target_ty.is_bfloat16()) {
1400	    bool from_type_is_e4m3 =
1401	        from_ty.is_float8_e4m3() || from_ty.is_float8_e4m3fn();
1402	    // PTX cvt encodes the fp8 type in the mnemonic, so pick the helper by name.
1403	    std::string cast_func = from_type_is_e4m3 ? "__tl_cvt_e4m3x2_to_bfloat162"
1404	                                              : "__tl_cvt_e5m2x2_to_bfloat162";
1405	    if (lanes == 2 || lanes == 4 || lanes == 8) {
1406	      PrintVectorizedCast(cast_func, "__maca_fp8x2_storage_t",
1407	                          "__maca_bfloat162", "", true, false);
1408	      return;
1409	    }
1410	  }
1411	
1412	  // Handle conversion from float8 (E8M0) to bfloat16
1413	  if (from_ty.is_float8_e8m0fnu() && target_ty.is_bfloat16()) {
1414	    // Use __tl_cvt_e8m0x2_to_bfloat162 for vectorized conversion (fp8_e8m0x2 ->
1415	    // bfloat162)
1416	    if (lanes == 2 || lanes == 4 || lanes == 8) {
1417	      PrintVectorizedCast("__tl_cvt_e8m0x2_to_bfloat162",
1418	                          "__maca_fp8x2_storage_t", "__maca_bfloat162", "",
1419	                          true, false);
1420	      return;
1421	    }
1422	  }
1423	
1424	  // Handle conversion from bfloat16 to float8 (E8M0)
1425	  if (from_ty.is_bfloat16() && target_ty.is_float8_e8m0fnu()) {
1426	    // Use __tl_cvt_bfloat162_to_e8m0x2 for vectorized conversion (bfloat162 ->
1427	    // fp8_e8m0x2)
1428	    if (lanes == 2 || lanes == 4 || lanes == 8) {
1429	      PrintVectorizedCast("__tl_cvt_bfloat162_to_e8m0x2", "__maca_bfloat162",
1430	                          "__maca_fp8x2_storage_t", "", false, true);
1431	      return;
1432	    }
1433	  }
1434	
1435	  // Handle conversion from float32 to float8 (E8M0)
1436	  if (from_ty.is_float() && from_ty.bits() == 32 &&
1437	      target_ty.is_float8_e8m0fnu()) {
1438	    // Use __tl_cvt_float2_to_e8m0x2 for vectorized conversion (float2 ->
1439	    // fp8_e8m0x2)
1440	    if (lanes == 2 || lanes == 4 || lanes == 8) {
1441	      PrintVectorizedCast("__tl_cvt_float2_to_e8m0x2", "float2",
1442	                          "__maca_fp8x2_storage_t", "", false, true);
1443	      return;
1444	    }
1445	  }
1446	
1447	  // Handle conversion from double to float8 (E8M0)
1448	  if (from_ty.is_float() && from_ty.bits() == 64 &&
1449	      target_ty.is_float8_e8m0fnu()) {
1450	    // Use __tl_cvt_double2_to_e8m0x2 for vectorized conversion (double2 ->
1451	    // fp8_e8m0x2)
1452	    if (lanes == 2 || lanes == 4 || lanes == 8) {
1453	      PrintVectorizedCast("__tl_cvt_double2_to_e8m0x2", "double2",
1454	                          "__maca_fp8x2_storage_t", "", false, true);
1455	      return;
1456	    }
1457	  }
1458	
1459	  // Handle conversion from float16 to float4 (E2M1)
1460	  if (from_ty.is_float16() && target_ty.is_float4_e2m1fn()) {
1461	    // Use __tl_cvt_half2_to_fp4x2 for vectorized conversion (half2 -> fp4x2)
1462	    if (lanes == 2 || lanes == 4 || lanes == 8) {
1463	      PrintVectorizedCast("__tl_cvt_half2_to_fp4x2", "half2", "uint8_t", "",
1464	                          false, true);
1465	      return;
1466	    }
1467	  }
1468	
1469	  // Handle conversion from float32 to float4 (E2M1)
1470	  if (from_ty.is_float() && from_ty.bits() == 32 &&
1471	      target_ty.is_float4_e2m1fn()) {
1472	    // Use __tl_cvt_float2_to_fp4x2 for vectorized conversion (float2 -> fp4x2)
1473	    if (lanes == 2 || lanes == 4 || lanes == 8) {
1474	      PrintVectorizedCast("__tl_cvt_float2_to_fp4x2", "float2", "uint8_t", "",
1475	                          false, true);
1476	      return;
1477	    }
1478	  }
1479	
1480	  // Handle conversion from float4 (E2M1) to float16
1481	  if (from_ty.is_float4_e2m1fn() && target_ty.is_float16()) {
1482	    // Use __tl_cvt_fp4x2_to_half2 for vectorized conversion (fp4x2 -> half2)
1483	    if (lanes == 2 || lanes == 4 || lanes == 8) {
1484	      PrintVectorizedCast("__tl_cvt_fp4x2_to_half2", "uint8_t", "half2", "",
1485	                          true, false);
1486	      return;
1487	    }
1488	  }
1489	
1490	  // Handle conversion from float4 (E2M1) to float32
1491	  if (from_ty.is_float4_e2m1fn() && target_ty.is_float() &&
1492	      target_ty.bits() == 32) {
1493	    // Use __tl_cvt_fp4x2_to_float2 for vectorized conversion (fp4x2 -> float2)
1494	    if (lanes == 2 || lanes == 4 || lanes == 8) {
1495	      PrintVectorizedCast("__tl_cvt_fp4x2_to_float2", "uint8_t", "float2", "",
1496	                          true, false);
1497	      return;
1498	    }
1499	  }
1500	
1501	  // Handle conversion from double to float4 (E2M1)
1502	  if (from_ty.is_float() && from_ty.bits() == 64 &&
1503	      target_ty.is_float4_e2m1fn()) {
1504	    // Use __tl_cvt_double2_to_fp4x2 for vectorized conversion (double2 ->
1505	    // fp4x2)
1506	    if (lanes == 2 || lanes == 4 || lanes == 8) {
1507	      PrintVectorizedCast("__tl_cvt_double2_to_fp4x2", "double2", "uint8_t", "",
1508	                          false, true);
1509	      return;
1510	    }
1511	  }
1512	
1513	  // Handle conversion from float4 (E2M1) to double
1514	  if (from_ty.is_float4_e2m1fn() && target_ty.is_float() &&
1515	      target_ty.bits() == 64) {
1516	    // Use __tl_cvt_fp4x2_to_double2 for vectorized conversion (fp4x2 ->
1517	    // double2)
1518	    if (lanes == 2 || lanes == 4 || lanes == 8) {
1519	      PrintVectorizedCast("__tl_cvt_fp4x2_to_double2", "uint8_t", "double2", "",
1520	                          true, false);
1521	      return;
1522	    }
1523	  }
1524	
1525	  // Handle conversion from bfloat16 to float4 (E2M1)
1526	  if (from_ty.is_bfloat16() && target_ty.is_float4_e2m1fn()) {
1527	    // Use __tl_cvt_bfloat162_to_fp4x2 for vectorized conversion (bfloat162 ->
1528	    // fp4x2)
1529	    if (lanes == 2 || lanes == 4 || lanes == 8) {
1530	      PrintVectorizedCast("__tl_cvt_bfloat162_to_fp4x2", "__maca_bfloat162",
1531	                          "uint8_t", "", false, true);
1532	      return;
1533	    }
1534	  }
1535	
1536	  // Handle conversion from float4 (E2M1) to bfloat16
1537	  if (from_ty.is_float4_e2m1fn() && target_ty.is_bfloat16()) {
1538	    // Use __tl_cvt_fp4x2_to_bfloat162 for vectorized conversion (fp4x2 ->
1539	    // bfloat162)
1540	    if (lanes == 2 || lanes == 4 || lanes == 8) {
1541	      PrintVectorizedCast("__tl_cvt_fp4x2_to_bfloat162", "uint8_t",
1542	                          "__maca_bfloat162", "", true, false);
1543	      return;
1544	    }
1545	  }
1546	
1547	  // Fallback: elementwise cast
1548	  // fp16<->bf16 elements load as native __half/bfloat16, where a direct
1549	  // `(bfloat16_t)(__half)` (or reverse) is an ambiguous conversion; route
1550	  // through float to disambiguate.
1551	  bool cross_half = (from_ty.is_float16() && target_ty.is_bfloat16()) ||
1552	                    (from_ty.is_bfloat16() && target_ty.is_float16());
1553	  for (int i = 0, lanes = from_ty.lanes(); i < lanes; ++i) {
1554	    std::ostringstream val;
1555	    val << "(";
1556	    PrintType(target_ty.element_of(), val);
1557	    val << ")(";
1558	    if (cross_half)
1559	      val << "(float)(";
1560	    PrintVecElemLoad(src, from_ty, i, val);
1561	    if (cross_half)
1562	      val << ")";
1563	    val << ")";
1564	    PrintVecElemStore(sret, target_ty, i, val.str());
1565	  }
1566	
1567	  os << sret;
1568	}
