1570	void CodeGenTileLangMACA::VisitExpr_(const MinNode *op, std::ostream &os) {
1571	  // TODO(wt): Consider vectorized reduction and impl for other dtypes
1572	  DataType t = op->dtype;
1573	
1574	  // Standard min/max functions don't support bfloat16 or float16
1575	  if ((t.is_bfloat16() || t.is_float16()) && t.is_scalar()) {
1576	    os << "__hmin(" << PrintExpr(op->a) << ", " << PrintExpr(op->b) << ")";
1577	    return;
1578	  }
1579	
1580	  // For float32 and float64 scalar, use standard min functions
1581	  if (t.is_float() && t.is_scalar()) {
1582	    if (t.bits() == 32 || t.bits() == 64) {
1583	      os << "min(" << PrintExpr(op->a) << ", " << PrintExpr(op->b) << ")";
1584	      return;
1585	    }
1586	  }
1587	
1588	  // For all other scalar types (int, uint), use default implementation
1589	  CodeGenC::VisitExpr_(op, os);
1590	}
