1614	void CodeGenTileLangMACA::PrintCallExtern(Type ret_type, String global_symbol,
1615	                                          const Array<PrimExpr> &args,
1616	                                          bool skip_first_arg,
1617	                                          std::ostream &os) { // NOLINT(*)
1618	  DataType ret_dtype = GetRuntimeDataType(ret_type);
1619	  if (ret_dtype.is_vector()) {
1620	    //
1621	    // Emit an unsupported vector call
1622	    //
1623	    // v = intrin_f((float4*)A[0], (float4*)B[0])
1624	    //
1625	    // as
1626	    //
1627	    // float4 __ret;
1628	    // {
1629	    //   float4 __arg0 = ((float4*)A)[0];
1630	    //   float4 __arg1 = ((float4*)B)[0];
1631	    //   __ret.x = intrin_f(__arg0.x, __arg1.x);
1632	    //   __ret.y = intrin_f(__arg0.y, __arg1.y);
1633	    //   __ret.z = intrin_f(__arg0.z, __arg1.z);
1634	    //   __ret.w = intrin_f(__arg0.w, __arg1.w);
1635	    // }
1636	    // v = __ret;
1637	    //
1638	    // Declare the result vector.
1639	    std::string sret = name_supply_->FreshName("_");
1640	    this->PrintIndent();
1641	    this->PrintType(ret_dtype, stream);
1642	    stream << ' ' << sret << ";\n";
1643	    {
1644	      // Load arguments.
1645	      std::vector<std::string> sargs;
1646	      size_t arg_begin = static_cast<size_t>(skip_first_arg);
1647	      for (size_t i = arg_begin; i < args.size(); ++i) {
1648	        std::string val = SSAGetID(PrintExpr(args[i]), args[i].dtype());
1649	        sargs.push_back(std::move(val));
1650	      }
1651	
1652	      // Emit a scalar call for each lane.
1653	      for (int i = 0; i < ret_dtype.lanes(); ++i) {
1654	        std::ostringstream scall;
1655	        scall << global_symbol << "(";
1656	        for (size_t j = 0; j < sargs.size(); ++j) {
1657	          if (j > 0)
1658	            scall << ", ";
1659	          PrintVecElemLoad(sargs[j], args[arg_begin + j].dtype(), i, scall);
1660	        }
1661	        scall << ")";
1662	        PrintVecElemStore(sret, ret_dtype, i, scall.str());
1663	      }
1664	    }
1665	    os << sret;
1666	  } else {
1667	    CodeGenC::PrintCallExtern(ret_type, global_symbol, args, skip_first_arg,
1668	                              os);
1669	  }
1670	}
