1672	// Print a reference expression to a buffer.
1673	std::string CodeGenTileLangMACA::GetBufferRef(DataType t,
1674	                                              const BufferNode *buffer,
1675	                                              PrimExpr index) {
1676	  const VarNode *buffer_var = buffer->data.get();
1677	  std::ostringstream os;
1678	  std::string vid = GetVarID(buffer_var);
1679	  std::string scope;
1680	  if (alloc_storage_scope_.count(buffer_var)) {
1681	    scope = alloc_storage_scope_.at(buffer_var);
1682	  }
1683	  // bool is_vol = IsVolatile(buffer_var);
1684	  // always false for tl mctlass backend.
1685	  bool is_vol = false;
1686	
1687	  auto ptr_cast = [this, is_vol, scope](DataType pointed_to) {
1688	    std::ostringstream ptr_os;
1689	    ptr_os << "(";
1690	    if (is_vol) {
1691	      ptr_os << "volatile ";
1692	    }
1693	    if (!scope.empty() && IsScopePartOfType()) {
1694	      PrintStorageScope(scope, ptr_os);
1695	    }
1696	    PrintType(pointed_to, ptr_os);
1697	    ptr_os << "*)";
1698	    return ptr_os.str();
1699	  };
1700	
1701	  DataType buffer_element_dtype = buffer->dtype;
1702	
1703	  std::string buffer_str = vid;
1704	  if (!HandleTypeMatch(buffer_var, buffer_element_dtype) || is_vol) {
1705	    std::stringstream temp;
1706	    temp << "(" << ptr_cast(buffer_element_dtype) << vid << ")";
1707	    buffer_str = temp.str();
1708	  }
1709	  if (scope.empty()) {
1710	    scope = GetPtrStorageScope(buffer->data);
1711	  }
1712	  if (scope == "local.var" || scope.find("local.descriptor") == 0) {
1713	    os << vid;
1714	    return os.str();
1715	  }
1716	  std::string index_str = PrintExpr(index);
1717	  if (t.bits() == 4 || (t.bits() == 1 && t.is_int())) {
1718	    // This is a special case, because CodegenMACA::PrintType()
1719	    // returns "int" for bool and for 4-bit integers. In most cases,
1720	    // we divide by the number of lanes to determine the index.
1721	    // However, the backing type for scalar int4 and scalar bool is
1722	    // int32.  Therefore, we need to divide by the ratio of their
1723	    // sizes in that case.
1724	    int div_factor = (t.lanes() == 1) ? (32 / t.bits()) : t.lanes();
1725	    index_str =
1726	        PrintExpr(arith::Analyzer().Simplify(truncdiv(index, div_factor)));
1727	    os << "*((" << ptr_cast(t) << vid << ")" << " + " << index_str << ")";
1728	  } else if (t == buffer_element_dtype) {
1729	    os << buffer_str << "[" << index_str << "]";
1730	  } else {
1731	    // Fix fp4 pointer arithmetic: fp4 elements are 4-bit packed 2 per byte.
1732	    // fp4* + n incorrectly advances n bytes (skipping 2n elements).
1733	    int div_factor = 1;
1734	    if (buffer_element_dtype.is_float4() && buffer_element_dtype.lanes() == 1) {
1735	      div_factor = 2;
1736	    }
1737	    index_str =
1738	        PrintExpr(arith::Analyzer().Simplify(truncdiv(index, div_factor)));
1739	    os << "*" << ptr_cast(t) << "(" << buffer_str << " + " << index_str << ")";
1740	  }
1741	
1742	  return os.str();
1743	}
1744	
1745	std::string CodeGenTileLangMACA::GetVecLoad(DataType t,
1746	                                            const BufferNode *buffer,
1747	                                            PrimExpr base) {
1748	  const VarNode *buffer_var = buffer->data.get();
1749	  std::string scope;
1750	  if (alloc_storage_scope_.count(buffer_var)) {
1751	    scope = alloc_storage_scope_.at(buffer_var);
1752	  }
1753	  if (scope.empty()) {
1754	    scope = GetPtrStorageScope(buffer->data);
1755	  }
1756	
1757	  if (scope != "global" || t.bits() * t.lanes() <= 128) {
1758	    return this->CodeGenC::GetVecLoad(t, buffer, base);
1759	  }
1760	  ICHECK_EQ(t.bits() * t.lanes(), 256)
1761	      << "Unsupported vector load size: " << t.bits() * t.lanes();
1762	  auto buffer_ref = this->GetBufferRef(t, buffer, base);
1763	  std::ostringstream os;
1764	  os << "tl::load_global_256(&(" << buffer_ref << "))";
1765	  return os.str();
1766	}
1767	
1768	void CodeGenTileLangMACA::PrintVecStore(const BufferNode *buffer, DataType t,
1769	                                        PrimExpr base,
1770	                                        const std::string &value) {
1771	  const VarNode *buffer_var = buffer->data.get();
1772	  std::string scope;
1773	  if (alloc_storage_scope_.count(buffer_var)) {
1774	    scope = alloc_storage_scope_.at(buffer_var);
1775	  }
1776	  if (scope.empty()) {
1777	    scope = GetPtrStorageScope(buffer->data);
1778	  }
1779	
1780	  if (scope != "global" || t.bits() * t.lanes() <= 128) {
1781	    this->CodeGenC::PrintVecStore(buffer, t, base, value);
1782	    return;
1783	  }
1784	  ICHECK_EQ(t.bits() * t.lanes(), 256)
1785	      << "Unsupported vector load size: " << t.bits() * t.lanes();
1786	  auto buffer_ref = this->GetBufferRef(t, buffer, base);
1787	  this->PrintIndent();
1788	  this->stream << "tl::store_global_256(&(" << buffer_ref << "), " << value
1789	               << ");\n";
1790	}
1791	
1792	/**
1793	 * @brief Emit MACA/Lib-specific code for a call expression.
1794	 *
1795	 * This visitor handles CallNode intrinsics and builtins that require emitting
1796	 * MACA/TL-specific code (inline ASM sequences, TensorLanguage runtime
1797	 * calls, WMMA/TMA helpers, barriers, cp.async primitives, index-map based
1798	 * stores, reinterpret/packing helpers, and various mma/ldmatrix patterns). The
1799	 * function writes the generated code to the provided output stream and falls
1800	 * back to the C codegen for unrecognized calls.
1801	 *
1802	 * The method recognizes and emits code for (non-exhaustive): cp.async and its
1803	 * commit/wait variants, tma_load/store and im2col variants,
1804	 * ldmatrix/stmatrix helpers, mbarrier APIs, cooperative grid sync, WMMA/legacy
1805	 * MMA intrinsics (fill/load/store/mma/bmma), low-level
1806	 * asm helpers (ldg32, cp_async bulk/init/arrive/wait barriers), reinterpret
1807	 * paths for special small-float encodings (e.g., float4 e2m1fn), tl::tl_gemm
1808	 * and related external calls, and other TL runtime calls.
1809	 *
1810	 * Side effects:
1811	 * - Emits to `os` and the internal codegen output stream.
1812	 * - May set internal feature flags (e.g., need_cooperative_groups_,
1813	 * need_mma_h_, need_cast_smem_ptr_to_int_, enable_sparse_gemm_).
1814	 * - May open/close SSA scopes and mutate internal variable mappings.
1815	 * - May call LOG(FATAL) / CHECK / ICHECK on invalid or unsupported argument
1816	 *   patterns.
1817	 *
1818	 * @param op The call node to generate code for; the function inspects op->op
1819	 *           and op->args to determine the appropriate emission.
1820	 * @param os  Output stream to receive expression-level output when the caller
1821	 *            expects an expression result (some paths write directly to the
1822	 *            member stream instead).
1823	 */
1824	void CodeGenTileLangMACA::VisitExpr_(const CallNode *op, std::ostream &os) {
1825	  auto print_extern_call_stmt = [&](std::string name, size_t start = 0,
1826	                                    size_t end = 0) {
1827	    // Cache context into a private ss, otherwise the let node may generate
1828	    // within the function call arguments.
1829	    std::ostringstream ss;
1830	
1831	    for (size_t i = start; i < op->args.size() - end; i++) {
1832	      if (i > start)
1833	        ss << ", ";
1834	      ss << this->PrintExpr(op->args[i]);
1835	    }
1836	
1837	    this->PrintIndent();
1838	    this->stream << name << "(";
1839	    this->stream << ss.str();
1840	    this->stream << ");\n";
1841	  };
1842	  if (op->op.same_as(tl::maca_memcpy_async())) {
1843	    // args[0] = dst_access_ptr, args[1] = src_access_ptr, args[2] = bytes,
1844	    // args[3] = barrier
1845	    ICHECK(op->args.size() == 4)
1846	        << "maca_memcpy_async expects 4 arguments (dst_access_ptr, "
1847	           "src_access_ptr, bytes, barrier)";
1848	
1849	    std::string dst = this->PrintExpr(op->args[0]);
1850	    std::string src = this->PrintExpr(op->args[1]);
1851	    std::string bytes = this->PrintExpr(op->args[2]);
1852	    std::string mbar = this->PrintExpr(op->args[3]);
1853	
1854	    this->PrintIndent();
1855	    this->stream << mbar << " = memcpy_async<" << bytes
1856	                 << ">((void* __restrict__)" << dst << ", (void* __restrict__)"
1857	                 << src << ");\n";
1858	  } else if (op->op.same_as(tl::maca_barrier_arrive_and_wait())) {
1859	    this->PrintIndent();
1860	    ICHECK(op->args.size() == 1)
1861	        << "maca_barrier_arrive_and_wait expects 1 argument (bar)";
1862	    std::string dummyRet = this->PrintExpr(op->args[0]);
1863	    this->stream << "barrier_arrive_and_wait(" << dummyRet << ");\n";
1864	  } else if (op->op.same_as(builtin::create_barriers())) {
1865	    this->PrintIndent();
1866	    int barrier_count = Downcast<IntImm>(op->args[0])->value;
1867	    auto mbarrier_storage_name = mbarrier_name_ + "_mem";
1868	    this->stream << "__shared__ __align__(" << barrier_alignment_bytes_
1869	                 << ") uint64_t " << mbarrier_storage_name << "["
1870	                 << barrier_count << "];\n";
1871	    this->PrintIndent();
1872	    this->stream << "auto " << mbarrier_name_ << " = reinterpret_cast<"
1873	                 << mbarrier_dtype_ << "*>(" << mbarrier_storage_name << ");\n";
1874	  } else if (op->op.same_as(tl::mbarrier_expect_tx())) {
1875	    ICHECK_EQ(op->args.size(), 2);
1876	    this->PrintIndent();
1877	    auto mbarrier_obj = this->PrintExpr(op->args[0]);
1878	    auto transaction_bytes = this->PrintExpr(op->args[1]);
1879	    this->stream << mbarrier_obj << ".expect_transaction(" << transaction_bytes
1880	                 << ");\n";
1881	  } else if (op->op.same_as(tl::mbarrier_wait_parity())) {
1882	    ICHECK_EQ(op->args.size(), 2);
1883	    this->PrintIndent();
1884	    auto mbarrier_obj = this->PrintExpr(op->args[0]);
1885	    auto phase = this->PrintExpr(op->args[1]);
1886	    this->stream << mbarrier_obj << ".wait(" << phase << ");\n";
1887	  } else if (op->op.same_as(tl::no_set_max_nreg())) {
1888	    return;
1889	  } else if (op->op.same_as(tl::tma_load())) {
1890	    std::ostringstream ss;
1891	    ICHECK_GE(op->args.size(), 2);
1892	    auto eviction_policy =
1893	        this->eviction_policy_names_
1894	            [op->args[op->args.size() - 1].as<IntImmNode>()->value];
1895	    // Simplify the code by using the default eviction policy
1896	    if (eviction_policy != "EVICT_NORMAL") {
1897	      ss << "tl::tma_load<tl::CacheHintSm90::" << eviction_policy << ">(";
1898	    } else {
1899	      ss << "tl::tma_load(";
1900	    }
1901	    auto desc = op->args[0];
1902	    ss << this->PrintExpr(desc) << ", ";
1903	    ss << this->PrintExpr(op->args[1]) << ", ";
1904	    for (size_t i = 2; i < op->args.size() - 1; i++) {
1905	      if (i > 2)
1906	        ss << ", ";
1907	      ss << this->PrintExpr(op->args[i]);
1908	    }
1909	    ss << ");\n";
1910	    this->PrintIndent();
1911	    this->stream << ss.str();
1912	  } else if (op->op.same_as(tl::tma_load_im2col())) {
1913	    std::stringstream ss;
1914	    auto eviction_policy =
1915	        this->eviction_policy_names_
1916	            [op->args[op->args.size() - 1].as<IntImmNode>()->value];
1917	    if (eviction_policy != "EVICT_NORMAL") {
1918	      ss << "tl::tma_load_im2col<tl::CacheHintSm90::" << eviction_policy << ">";
1919	    } else {
1920	      ss << "tl::tma_load_im2col";
1921	    }
1922	    print_extern_call_stmt(ss.str(), 0, 1);
1923	  } else if (op->op.same_as(tl::tma_store())) {
1924	    std::stringstream ss;
1925	    auto need_reduce = op->args[op->args.size() - 2].as<IntImmNode>()->value;
1926	    if (need_reduce) {
1927	      print_extern_call_stmt("tl::tma_store_add", 0, 2);
1928	      return;
1929	    }
1930	    auto eviction_policy =
1931	        this->eviction_policy_names_
1932	            [op->args[op->args.size() - 1].as<IntImmNode>()->value];
1933	    if (eviction_policy != "EVICT_NORMAL") {
1934	      ss << "tl::tma_store<tl::CacheHintSm90::" << eviction_policy << ">";
1935	    } else {
1936	      ss << "tl::tma_store";
1937	    }
1938	    print_extern_call_stmt(ss.str(), 0, 2);
1939	  } else if (op->op.same_as(tl::fence_proxy_async())) {
1940	    print_extern_call_stmt("tl::fence_proxy_async");
1941	  } else if (op->op.same_as(tl::tma_store_arrive())) {
1942	    print_extern_call_stmt("tl::tma_store_arrive");
1943	  } else if (op->op.same_as(tl::tma_store_wait())) {
1944	    int count = Downcast<IntImm>(op->args[0])->value;
1945	    this->PrintIndent();
1946	    this->stream << "tl::tma_store_wait<" << count << ">();\n";
1947	  } else if (op->op.same_as(tl::warpgroup_arrive())) {
1948	    print_extern_call_stmt("tl::warpgroup_arrive");
1949	  } else if (op->op.same_as(tl::warpgroup_commit_batch())) {
1950	    print_extern_call_stmt("tl::warpgroup_commit_batch");
1951	  } else if (op->op.same_as(tl::warpgroup_wait())) {
1952	    this->PrintIndent();
1953	    int num_mma = Downcast<IntImm>(op->args[0])->value;
1954	    this->stream << "tl::warpgroup_wait<" << std::to_string(num_mma)
1955	                 << ">();\n";

