36	struct MACAMath {
37	  std::string operator()(DataType t, std::string name) const {
38	    if (t.is_float()) {
39	      switch (t.bits()) {
40	      case 64:
41	        return name;
42	      case 32:
43	        return name + 'f';
44	      case 16: {
45	        if (name == "fabs") {
46	          return "__habs";
47	        } else if (name == "round") {
48	          return "hrint";
49	        } else {
50	          return "h" + name;
51	        }
52	      }
53	      default:
54	        return "";
55	      }
56	    } else if (t.is_bfloat16()) {
57	      if (name == "fabs") {
58	        return "__habs";
59	      }
60	      return 'h' + name;
61	    } else if (t.is_int() || t.is_uint()) {
62	      switch (t.bits()) {
63	      case 32:
64	        return "__" + name;
65	      case 64:
66	        return "__" + name + "ll";
67	      default:
68	        return "";
69	      }
70	    }
71	    return "";
72	  }
