17	static std::string GetDeviceGlobalSymbol(const GlobalVar &gvar,
18	                                         const tirx::PrimFunc &f) {
19	  if (auto global_symbol = f->GetAttr<ffi::String>(tvm::attr::kGlobalSymbol)) {
20	    return static_cast<std::string>(global_symbol.value());
21	  }
22	  return gvar->name_hint;
23	}
24	
25	static void ValidateUniqueDeviceGlobalSymbols(const IRModule &mod) {
26	  std::unordered_map<std::string, std::string> symbol_to_gvar;
27	
28	  for (auto kv : mod->functions) {
29	    ICHECK(kv.second->IsInstance<tirx::PrimFuncNode>())
30	        << "Can only lower IR Module with PrimFuncs";
31	    auto gvar = Downcast<GlobalVar>(kv.first);
32	    auto f = Downcast<tirx::PrimFunc>(kv.second);
33	    std::string global_symbol = GetDeviceGlobalSymbol(gvar, f);
34	
35	    auto [it, inserted] =
36	        symbol_to_gvar.emplace(global_symbol, gvar->name_hint);
37	    ICHECK(inserted)
38	        << "Duplicate MACA kernel global_symbol `" << global_symbol
39	        << "` found on PrimFuncs `" << it->second << "` and `"
40	        << gvar->name_hint
41	        << "`. T.MACASourceCodeKernel emits raw MACA source without "
42	           "renaming, so MACA entry names must be unique within the compiled "
43	           "module.";
44	  }
45	}
46	
47	static Map<String, runtime::FunctionInfo> ExtractFuncInfo(const IRModule &mod) {
48	  Map<String, runtime::FunctionInfo> fmap;
49	
50	  for (auto kv : mod->functions) {
51	    ICHECK(kv.second->IsInstance<tirx::PrimFuncNode>())
52	        << "Can only lower IR Module with PrimFuncs";
53	    auto f = Downcast<tirx::PrimFunc>(kv.second);
54	
55	    Array<DLDataType> arg_types;
56	    Array<String> launch_param_tags;
57	
58	    runtime::FunctionInfo info;
59	    for (size_t i = 0; i < f->params.size(); ++i) {
60	      if (f->params[i]->dtype.is_handle()) {
61	        auto ptr = f->params[i]->type_annotation.as<PointerTypeNode>();
62	        if (ptr && ptr->storage_scope == "grid_constant") {
63	          arg_types.push_back(DataType(runtime::kDLGridConstant, 64, 1));
64	          continue;
65	        }
66	      }
67	      DataType dtype = f->params[i].dtype();
68	      // Device runtime cannot directly take bool arguments, map to int32.
69	      if (dtype.is_bool())
70	        dtype = DataType::Int(32);
71	      arg_types.push_back(dtype);
72	    }
73	    if (f->HasNonzeroAttr(tl::attr::kHasGridSync)) {
74	      launch_param_tags.push_back(
75	          runtime::launch_param::kUseProgramaticDependentLaunch);
76	    }
77	    if (f->HasNonzeroAttr("use_cooperative_groups")) {
78	      launch_param_tags.push_back(runtime::launch_param::kUseCooperativeLaunch);
79	    }
80	    if (f->GetAttr<Array<Integer>>("cluster_dims").defined()) {
81	      launch_param_tags.push_back(runtime::launch_param::kClusterDimX);
82	      launch_param_tags.push_back(runtime::launch_param::kClusterDimY);
83	      launch_param_tags.push_back(runtime::launch_param::kClusterDimZ);
84	    }
85	    if (auto opt = f->GetAttr<Array<String>>(tirx::attr::kKernelLaunchParams)) {
86	      for (const auto &tag : opt.value()) {
87	        if (tag != runtime::launch_param::kClusterDimX &&
88	            tag != runtime::launch_param::kClusterDimY &&
89	            tag != runtime::launch_param::kClusterDimZ) {
90	          launch_param_tags.push_back(tag);
91	        }
92	      }
93	    }
94	    std::string sym = GetDeviceGlobalSymbol(Downcast<GlobalVar>(kv.first), f);
95	    fmap.Set(String(sym), runtime::FunctionInfo(String(sym), arg_types,
96	                                                launch_param_tags, {}));
97	  }
98	  return fmap;
99	}
