      this->PrintExpr(op->args[0], os);
      os << ", ";
      this->PrintExpr(op->args[1], os);
      os << ", ";
      this->PrintExpr(op->args[2], os);
    } else {
      os << "tl::store_global_128(";
      this->PrintExpr(op->args[0], os);
      os << ", ";
      this->PrintExpr(op->args[1], os);
    }
