37	
38	namespace tvm {
39	namespace tl {
40	using namespace tirx;
41	using namespace ffi;
42	
43	class IntrinInjecter : public tvm::arith::IRMutatorWithAnalyzer {
44	public:
45	  using IRMutatorWithAnalyzer::VisitExpr_;
46	  using IRMutatorWithAnalyzer::VisitStmt_;
47	  using FLowerGeneral = TypedFunction<PrimExpr(PrimExpr)>;
48	
49	  IntrinInjecter(arith::Analyzer *analyzer, std::string target,
50	                 std::string mtriple = "")
51	      : IRMutatorWithAnalyzer(analyzer) {
52	    std::vector<std::string> patterns;
53	    patterns.push_back(target + ".FLowerIntrinsic");
54	    patterns.push_back(target + ".FLegalize");
55	    bool is_llvm_aarch64 = (mtriple.find("aarch64") != std::string::npos);
56	    if (is_llvm_aarch64) {
57	      patterns.push_back(target + ".aarch64.FLowerIntrinsic");
58	      patterns.push_back(target + ".aarch64.FLegalize");
59	    }
60	    patterns.push_back("default.FLowerIntrinsic");
61	    patterns.push_back("default.FLegalize");
62	
63	    for (const std::string &pattern : patterns)
64	      if (Op::HasAttrMap(pattern)) {
65	        attr_maps_.push_back(Op::GetAttrMap<FLowerGeneral>(pattern));
66	        if (fma_ == nullptr) {
67	          fma_ = (*attr_maps_.rbegin()).get(Op::Get("tirx.fma"), nullptr);
68	        }
69	      }
70	  }
71	
72	  PrimExpr VisitExpr_(const CallNode *op) final {
73	    if (auto *ptr_op = op->op.as<OpNode>()) {
74	      for (const auto &f_attr_map : attr_maps_) {
75	        FLowerGeneral f = f_attr_map.get(GetRef<Op>(ptr_op), nullptr);
76	        if (f != nullptr) {
77	          PrimExpr e = GetRef<PrimExpr>(op);
78	          PrimExpr r = f(e);
79	          ICHECK(r.defined()) << "intrinsic rule must always return valid Expr";
80	          if (!r.same_as(e)) {
81	            r = this->VisitExpr(r);
82	            if (r.defined()) {
83	              return r;
84	            }
85	          }
86	        }
87	      }
88	    }
89	    return IRMutatorWithAnalyzer::VisitExpr_(op);
90	  }
91	
92	  PrimExpr VisitExpr_(const AddNode *op) final {
93	    if (const MulNode *mb = op->b.as<MulNode>()) {
94	      return MakeFMA(mb->a, mb->b, op->a, op);
95	    } else if (const MulNode *ma = op->a.as<MulNode>()) {
96	      return MakeFMA(ma->a, ma->b, op->b, op);
97	    }
98	    return IRMutatorWithAnalyzer::VisitExpr_(op);
99	  }
100	
101	  // We use floordiv for integer analysis,
102	  // but will need to lower them to native truncdiv instructions
103	  PrimExpr VisitExpr_(const FloorDivNode *op) final {
104	    auto e = GetRef<PrimExpr>(op);
105	    PrimExpr ret = IRMutatorWithAnalyzer::VisitExpr_(op);
106	    op = ret.as<FloorDivNode>();
107	    if (op == nullptr)
108	      return ret;
109	    int shift;
110	    const DataType &dtype = op->dtype;
111	    ICHECK(dtype.is_int() || dtype.is_uint());
112	
113	    // lower (a + 31) // 512 to (a + 31) >> 5
114	    if (support_bitwise_op_ && is_const_power_of_two_integer(op->b, &shift)) {
115	      // lower to right shift if possible.
116	      return op->a >> make_const(dtype, shift);
117	    }
118	
119	    if (analyzer_->CanProveGreaterEqual(op->b, 0)) {
120	      // Common path, positive divisor
121	      if (analyzer_->CanProveGreaterEqual(op->a, 0) ||
122	          analyzer_->CanProveGreaterEqual(e, 0)) {
123	        return truncdiv(op->a, op->b);
124	      }
125	
126	      // NOTE: Disabled due to integer overflow risk in `a + b * c`.
127	      // The transformation `floordiv(a,b) -> truncdiv(a + b*c, b) - c`
128	      // may overflow when `a` is near type limit and `c` is large,
129	      // producing incorrect results.
130	
131	      // If the numerator's lower bound is known, express the floordiv
132	      // in terms of truncdiv using only positive operands.
133	      /*
134	      arith::ConstIntBound const_int_bound = analyzer_->const_int_bound(op->a);
135	      if (const_int_bound->min_value < 0 &&
136	          const_int_bound->min_value >
137	              -(Downcast<IntImm>(tvm::max_value(op->a->dtype.element_of()))
138	                    ->value)) {
139	        // The goal is to write floordiv(a,b) in terms of truncdiv, without
140	        // using negative operands.
141	        //
142	        // For any integer c
143	        //
144	        //   floordiv(a,b) == floordiv(a + b*c - b*c, b)
145	        //                 == floordiv(a + b*c, b) - c
146	        //
147	        // Choosing `c = ceildiv(-a_min, b)`.  This can be rewritten in terms of
148	        // truncdiv as follows.
149	        //
150	        //   c == ceildiv(-a_min,b)
151	        //     == floordiv(-a_min + (b-1), b)
152	        //     == truncdiv(-a_min + (b-1), b)
153	        //
154	        // When substituted into `a + b*c`, this results in a positive argument.
155	        //
156	        //   a + b*c
157	        //     == a + b*ceildiv(-a_min,b)
158	        //     == a - b*floordiv(a_min,b)
159	        //     >= a - b*floordiv(a,b)
160	        //     == floormod(a, b)
161	        //     >= 0
162	        //
163	        // Since the argument is positive, this allows floordiv to be written as
164	        // followed.
165	        //
166	        //   floordiv(a,b)
167	        //     == floordiv(a + b*c, b) - c
168	        //     == truncdiv(a + b*c, b) - c
169	        IntImm min(op->a->dtype.element_of(), const_int_bound->min_value);
170	        PrimExpr ceildiv = truncdiv((op->b - 1) - min, op->b);
171	        PrimExpr offset_numerator =
172	            analyzer_->Simplify(op->a + op->b * ceildiv);
173	        return truncdiv(offset_numerator, op->b) - ceildiv;
174	      }
175	      */
176	
177	      DLOG(INFO) << "LowerFloorDiv: Cannot decide the sign of divident";
178	      PrimExpr rdiv = truncdiv(op->a, op->b);
179	      PrimExpr rmod = truncmod(op->a, op->b);
180	      // condition on b >= 0.
181	      // truncmod(a, b) < 0 will implies ceildiv,
182	      // So we need to correct these cases.
183	      if ((dtype == DataType::Int(32) || dtype == DataType::Int(64)) &&
184	          support_bitwise_op_) {
185	        // equivalent to rdiv + (rmod >= 0 ? 0: -1);
186	        return rdiv + (rmod >> make_const(dtype, dtype.bits() - 1));
187	      } else {
188	        return tirx::Select(rmod >= 0, rdiv, rdiv - make_const(dtype, 1));
189	      }
190	
191	    } else {
192	      if (dtype.is_float()) {
193	        // floor(a / b)
194	        return VisitExpr_(tvm::floor(op->a / op->b).as<CallNode>());
195	      } else {
196	        // uncommon case
197	        DLOG(INFO) << "LowerFloorDiv: Cannot decide the sign of divisor";
198	        auto rmod = tirx::Var("rmod", dtype);
199	        auto rdiv = tirx::Var("rdiv", dtype);
200	        // b >= 0 => (rmod >=0 ? rdiv : rdiv - 1)
201	        // b < 0  => (rmod <= 0 ? rdiv : rdiv - 1)
202	        PrimExpr let_rdiv = tirx::Let(
203	            rdiv, truncdiv(op->a, op->b),
204	            tirx::Select((op->b >= 0 && rmod >= 0) || (op->b < 0 && rmod <= 0),
205	                         rdiv, rdiv - make_const(dtype, 1)));
206	        return Let(rmod, truncmod(op->a, op->b), let_rdiv);
207	      }
208	    }
209	  }
210	
211	  PrimExpr VisitExpr_(const FloorModNode *op) final {
212	    PrimExpr ret = IRMutatorWithAnalyzer::VisitExpr_(op);
213	    op = ret.as<FloorModNode>();
214	    if (op == nullptr)
215	      return ret;
216	    // Lower floordiv to native truncdiv.
217	    int shift;
218	    const DataType &dtype = op->dtype;
219	    ICHECK(dtype.is_int() || dtype.is_uint());
220	
221	    if (support_bitwise_op_ && is_const_power_of_two_integer(op->b, &shift)) {
222	      // lower to masking if possible.
223	      int64_t mask =
224	          (static_cast<int64_t>(1) << static_cast<int64_t>(shift)) - 1;
225	      return op->a & make_const(dtype, mask);
226	    }
227	
228	    if (analyzer_->CanProveGreaterEqual(op->b, 0)) {
229	      // Common pass, positive divisor
230	      if (analyzer_->CanProveGreaterEqual(op->a, 0)) {
231	        return truncmod(op->a, op->b);
232	      }
233	
234	      // NOTE: Disabled due to integer overflow risk in `a + b * c`.
235	      // The transformation `floordiv(a,b) -> truncdiv(a + b*c, b) - c`
236	      // may overflow when `a` is near type limit and `c` is large,
237	      // producing incorrect results.
238	
239	      // If the numerator's lower bound is known, express the floormod
240	      // in terms of truncmod using only positive operands.
241	      /*
242	      arith::ConstIntBound const_int_bound = analyzer_->const_int_bound(op->a);
243	      if (const_int_bound->min_value < 0 &&
244	          const_int_bound->min_value >
245	              -(Downcast<IntImm>(tvm::max_value(op->a->dtype.element_of()))
246	                    ->value)) {
247	        // The goal is to write floormod(a,b) in terms of truncdiv and truncmod,
248	        // without using negative operands.
249	        //
250	        // For any integer c
251	        //
252	        //   floormod(a, b) == floormod(a + b*c, b)
253	        //
254	        // Choosing `c = ceildiv(-a_min, b)`.  This can be rewritten in terms of
255	        // truncdiv as follows.
256	        //
257	        //   c == ceildiv(-a_min,b)
258	        //     == floordiv(-a_min + (b-1), b)
259	        //     == truncdiv(-a_min + (b-1), b)
260	        //
261	        // When substituted into `a + b*c`, this results in a positive argument.
262	        //
263	        //   a + b*c
264	        //     == a + b*ceildiv(-a_min,b)
265	        //     == a - b*floordiv(a_min,b)
266	        //     >= a - b*floordiv(a,b)
267	        //     == floormod(a, b)
268	        //     >= 0
269	        //
270	        // Since the argument is positive, this allows floordiv to be written as
271	        // followed.
272	        //
273	        //   floormod(a,b)
274	        //     == floormod(a + b*c, b)
275	        //     == truncmod(a + b*c, b)
276	        IntImm min(op->a->dtype.element_of(), const_int_bound->min_value);
277	        PrimExpr ceildiv = truncdiv(-min + (op->b - 1), op->b);
278	        PrimExpr offset_numerator =
279	            analyzer_->Simplify(op->a + op->b * ceildiv);
280	        return truncmod(offset_numerator, op->b);
281	      }
282	      */
283	
284	      DLOG(INFO) << "LowerFloorMod: Cannot decide the sign of divident";
285	      // NOTE:condition on b >= 0.
286	      // mod(a, b) < 0 will imply we are doing ceildiv,
287	      // So we need to correct these cases.
288	      PrimExpr rmod = truncmod(op->a, op->b);
289	      if ((dtype == DataType::Int(32) || dtype == DataType::Int(64)) &&
290	          support_bitwise_op_) {
291	        // (rmod >> shift) & b
292	        // -> (rmod >= 0 ? 0: -1) & b
293	        // -> rmod >= 0 ? 0 : b
294	        return rmod + (op->b & (rmod >> make_const(dtype, dtype.bits() - 1)));
295	      } else {
296	        return tirx::Select(rmod >= 0, rmod, rmod + op->b);
297	      }
298	
299	    } else {
300	      if (dtype.is_float()) {
301	        // a - floor(a / b) * b
302	        return op->a -
303	               (VisitExpr_(tvm::floor(op->a / op->b).as<CallNode>()) * op->b);
304	      } else {
305	        // uncommon case
306	        DLOG(INFO)
307	            << "LowerFloorMod: Cannot decide the sign of divsor and divident";
308	        auto rmod = tirx::Var("rmod", dtype);
309	        // b > 0 && rmod >= 0 -> rmod
310	        // b > 0 && rmod < 0  -> rmod + b
311	        // b < 0 && rmod < 0 -> rmod
312	        // b < 0 && rmod > 0 -> rmod + b
313	        return Let(rmod, truncmod(op->a, op->b),
314	                   Select((op->b >= 0 && rmod >= 0) || (op->b < 0 && rmod <= 0),
315	                          rmod, rmod + op->b));
316	      }
317	    }
318	  }
319	
320	  PrimExpr VisitExpr_(const MaxNode *op) final {
321	    using namespace arith;
322	    PVar<PrimExpr> x, y;
323	    PVar<IntImm> c;
324	    auto e = GetRef<PrimExpr>(op);
325	    if (max(floordiv(x, y), c).Match(e) && c.Eval()->value >= 0 &&
326	        analyzer_->CanProveGreaterEqual(y.Eval(), 0)) {
327	      return max(VisitExpr(truncdiv(x, y).Eval()), c.Eval());
328	    }
329	    return IRMutatorWithAnalyzer::VisitExpr_(op);
330	  }
331	
332	  PrimExpr VisitExpr_(const EQNode *op) final {
333	    using namespace arith;
334	    PVar<PrimExpr> x, y;
335	    auto e = GetRef<PrimExpr>(op);
336	    if ((floormod(x, y) == 0).Match(e)) {
337	      return VisitExpr((truncmod(x, y) == 0).Eval());
338	    }
339	    return IRMutatorWithAnalyzer::VisitExpr_(op);
340	  }
341	
342	  PrimExpr VisitExpr_(const NENode *op) final {
343	    using namespace arith;
344	    PVar<PrimExpr> x, y;
345	    auto e = GetRef<PrimExpr>(op);
346	    if ((floormod(x, y) != 0).Match(e)) {
347	      return VisitExpr((truncmod(x, y) != 0).Eval());
348	    }
349	    return IRMutatorWithAnalyzer::VisitExpr_(op);
350	  }
351	
352	private:
353	  PrimExpr SwapBroadcastCast(const PrimExpr &e) {
354	    // Try to change broadcast(cast(x)) to cast(broadcast(x))
355	    // For some targets, LLVM will generate more efficient FMA
356	    // instruction with the latter. For example, vmla vs. vmlal
357	    // on ARM.
358	    if (const BroadcastNode *bcast = e.as<BroadcastNode>()) {
359	      if (const CastNode *cast = bcast->value.as<CastNode>()) {
360	        auto should_swap = [&]() {
361	          // Maintain behaviour (int8 -> int16, fp16 -> fp32).
362	          if (cast->dtype.bits() == cast->value.dtype().bits() * 2) {
363	            return true;
364	          }
365	          // Check both operands are integer-like.
366	          if (!cast->dtype.is_uint() && !cast->dtype.is_int()) {
367	            return false;
368	          }
369	          if (!cast->value.dtype().is_uint() && !cast->value.dtype().is_int()) {
370	            return false;
371	          }
372	          // If both are integer-like, swap if we have a widening cast.
373	          return cast->dtype.bits() > cast->value.dtype().bits();
374	        };
375	
376	        if (should_swap()) {
377	          PrimExpr new_bcast = Broadcast(cast->value, bcast->lanes);
378	          return Cast(bcast->dtype, new_bcast);
379	        }
380	      }
381	    }
382	    return e;
383	  }
384	
385	  PrimExpr MakeFMA(const PrimExpr &a, const PrimExpr &b, const PrimExpr &c,
386	                   const AddNode *op) {
387	    // emit fma instruction: a * b + c
388	    PrimExpr lhs = SwapBroadcastCast(a);
389	    PrimExpr rhs = SwapBroadcastCast(b);
390	
391	    if (fma_ != nullptr && op->dtype.is_float()) {
392	      PrimExpr r = fma_(Call(op->dtype, builtin::fma(), {lhs, rhs, c}));
393	      if (r.defined())
394	        return this->VisitExpr(r);
395	    } else {
396	      if (!lhs.same_as(a) || !rhs.same_as(b)) {
397	        PrimExpr mul = this->VisitExpr(Mul(lhs, rhs));
398	        return Add(mul, this->VisitExpr(c));
399	      }
400	    }
401	    return IRMutatorWithAnalyzer::VisitExpr_(op);
402	  }
403	
404	  // attribute maps, shared only when FLegalize == FLowerIntrinsic
405	  std::vector<OpAttrMap<FLowerGeneral>> attr_maps_;
406	  FLowerGeneral fma_{nullptr};
407	  bool support_bitwise_op_{true};
408	};
409	
410	Stmt LowerIntrinStmt(Stmt stmt, const std::string &target) {
411	  arith::Analyzer analyzer;
412	  return IntrinInjecter(&analyzer, target)(std::move(stmt));
413	}
414	
415	namespace transform {
416	
417	tirx::transform::Pass LowerIntrin() {
418	  using namespace tirx::transform;
419	  auto pass_func = [](PrimFunc f, IRModule m, PassContext ctx) {
420	    auto *n = f.CopyOnWrite();
421	    auto target = f->GetAttr<Target>(tvm::attr::kTarget);
422	    ICHECK(target.defined()) << "LowerIntrin: Require the target attribute";
423	    arith::Analyzer analyzer;
424	    auto mtriple = target.value()->GetAttr<String>("mtriple", "");
425	    n->body = IntrinInjecter(&analyzer, target.value()->kind->name,
426	                             mtriple.value())(std::move(n->body));
427	    return f;
428	  };
429	  return CreatePrimFuncPass(pass_func, 0, "tl.LowerIntrin", {});
430	}
431	
432	TVM_FFI_STATIC_INIT_BLOCK() {
433	  namespace refl = reflection;
434	  refl::GlobalDef().def("tl.transform.LowerIntrin", LowerIntrin);
435	}
436	
437	} // namespace transform
438	
439	} // namespace tl
440	} // namespace tvm
